    def confirmed_rate_samples(rates: list[int]) -> list[dict[str, Any]]:
        confirmed = 0
        simulation = 0
        result: list[dict[str, Any]] = [{
            "state": ACTIVE_STATE,
            "state_name": "active",
            "round_phase_name": "active",
            "round_generation": 1,
            "round_epoch": 0x2222,
            "confirmed_frame": 0,
            "production_simulation_tick_calls": 0,
            "ts_qpc": QPC_FREQUENCY,
        }]
        for second, rate in enumerate(rates, start=1):
            confirmed += rate
            simulation += 60
            result.append({
                **result[0],
                "confirmed_frame": confirmed,
                "production_simulation_tick_calls": simulation,
                "ts_qpc": (second + 1) * QPC_FREQUENCY,
            })
        return result

