def legacy_beta_release_gate(args: argparse.Namespace) -> int:
    report_path = args.report or (
        REPO / "reports" / "rollback_two_client" /
        f"beta-release-{datetime.now():%Y%m%d-%H%M%S}.json"
    )
    aggregate: dict[str, Any] = {
        "report_schema_version": REPORT_SCHEMA_VERSION,
        "oracle_schema_version": ROLLBACK_ORACLE_SCHEMA_VERSION,
        "workflow": "beta-release-gate",
        "classification": "live",
        "generated_at": utc_now(),
        "ok": False,
        "verdict": "incomplete",
        "artifact": {},
        "stages": [],
        "failures": [],
    }

    def save() -> None:
        atomic_json(report_path, aggregate)

    def run_stage(name: str, command: list[str], timeout: float) -> bool:
        started = time.time()
        try:
            result = subprocess.run(
                command, cwd=REPO, text=True,
                stdout=subprocess.PIPE, stderr=subprocess.STDOUT,
                timeout=timeout, check=False,
            )
            output = result.stdout or ""
            stage = {
                "name": name, "command": command,
                "returncode": result.returncode,
                "seconds": time.time() - started,
                "output_tail": output[-12000:],
                "ok": result.returncode == 0,
            }
        except (OSError, subprocess.TimeoutExpired) as exc:
            stage = {
                "name": name, "command": command, "ok": False,
                "seconds": time.time() - started,
                "error": f"{type(exc).__name__}:{exc}",
            }
        aggregate["stages"].append(stage)
        if not stage["ok"]:
            aggregate["failures"].append(f"stage:{name}")
        save()
        return bool(stage["ok"])

    if not args.replay_file or not args.replay_file.is_file():
        aggregate["failures"].append("missing-beta-replay-file")
    if not args.manual_attach_report \
            or not args.manual_attach_report.is_file():
        aggregate["failures"].append("missing-manual-attach-report")
    if not args.release_qualification_manifest \
            or not args.release_qualification_manifest.is_file():
        aggregate["failures"].append(
            "missing-two-machine-release-qualification")
    if aggregate["failures"]:
        save()
        print(f"report={report_path}")
        return 2

    oracle_args = argparse.Namespace(**vars(args))
    oracle_args.require_round_rearm = True
    # The normal replay process extracts and reports the authoritative seed.
    # This preliminary pass only selects a viable correction window.
    if oracle_args.replay_random_seed_arg is None:
        oracle_args.replay_random_seed_arg = 1
    try:
        prepare_replay_input(oracle_args)
        oracle_window_start, oracle_window_end = replay_oracle_logical_window(
            oracle_args.correction_start, oracle_args.hold_updates)
    except (OSError, ValueError, KeyError) as exc:
        aggregate["failures"].append(f"oracle-input-preflight:{exc}")
        save()
        print(f"report={report_path}")
        return 2

    kill_clients()
    sandbox_dll = sandbox_deployed_dll(
        args.sandbox_root, args.sandbox_box)
    try:
        selected_dll = args.built_dll.resolve()
        if not selected_dll.is_file():
            raise RuntimeError("reviewed-candidate-dll-missing")
        deploy_selected_candidate(selected_dll, sandbox_dll)
        require_deployment_preflight(sandbox_dll, args.built_dll.resolve())
        require_expected_artifact_hash(
            sandbox_dll, args.expected_artifact_sha256,
            built_dll=args.built_dll.resolve())
    except (OSError, RuntimeError) as exc:
        aggregate["failures"].append(f"deployment-preflight:{exc}")
        save()
        print(f"report={report_path}")
        return 1
    artifact_hash = sha256_file(selected_dll)
    aggregate["stages"].append({
        "name": "deploy-reviewed-candidate",
        "source": str(selected_dll),
        "artifact_sha256": artifact_hash,
        "ok": True,
    })
    aggregate["artifact"] = capture_evidence_identity(
        sandbox_dll, args.built_dll.resolve())
    save()
    if not run_stage("physical-two-machine-qualification", [
            sys.executable,
            str(REPO / "tools" / "rollback_two_machine_qualification.py"),
            "--validate", str(args.release_qualification_manifest),
        ], 300):
        print(f"report={report_path}")
        return 1
    try:
        qualification = json.loads(
            args.release_qualification_manifest.read_text(encoding="utf-8"))
    except (OSError, ValueError):
        qualification = {}
    if str(qualification.get("dll_sha256", "")).lower() != artifact_hash:
        aggregate["failures"].append(
            "two-machine-qualification-dll-mismatch")
    if qualification.get("transport") != STEAM_BETA_TRANSPORT:
        aggregate["failures"].append(
            "two-machine-qualification-transport-mismatch")
    if aggregate["failures"]:
        save()
        print(f"report={report_path}")
        return 1

    presubmit_build_root = (
        report_path.parent / f"{report_path.stem}-presubmit-builds"
    )
    presubmit_report = (
        report_path.parent / f"{report_path.stem}-presubmit.json"
    )
    if not run_stage("fresh-rollback-presubmit-matrix", [
            sys.executable,
            str(REPO / "tools" / "rollback_presubmit_matrix.py"),
            "--build-root", str(presubmit_build_root),
            "--report", str(presubmit_report),
        ], 3600):
        print(f"report={report_path}")
        return 1

    if not run_stage(
            "build:HorseModRollbackSelfTests",
            ["cmd", "/d", "/s", "/c",
             str(REPO / "build_horse_mod.bat"),
             "HorseModRollbackSelfTests"], 1200):
        print(f"report={report_path}")
        return 1
    try:
        rollback_selftests = discover_rollback_selftests(BUILD_DIR)
    except RollbackCTestError as exc:
        aggregate["failures"].append(f"ctest-discovery:{exc}")
        save()
        print(f"report={report_path}")
        return 1
    for test in rollback_selftests:
        if not run_stage(
                f"selftest:{test.name}", list(test.command), 240):
            print(f"report={report_path}")
            return 1
    for script, extra in (
        (REPO / "tools" / "sc6_launch_catalog_selftest.py", []),
        (REPO / "tools" / "replay_input_script_selftest.py", []),
        (REPO / "tools" / "rollback_golden_trace.py", ["--selftest"]),
        (REPO / "tools" / "rollback_two_machine_qualification.py",
         ["--selftest"]),
        (Path(__file__).resolve(), ["--selftest"]),
        (Path(__file__).resolve(), ["--policy-lint"]),
    ):
        stage_kind = "policy-lint" if "--policy-lint" in extra \
            else "selftest"
        if not run_stage(f"{stage_kind}:{script.name}",
                         [sys.executable, str(script), *extra], 300):
            print(f"report={report_path}")
            return 1

    oracle_dir = report_path.parent / f"{report_path.stem}-oracle"
    oracle_command = normal_replay_oracle_command(
        args.replay_file, oracle_dir)
    if not run_stage(
            "generate-normal-replay-oracle", oracle_command,
            NORMAL_REPLAY_ORACLE_STAGE_TIMEOUT_SECONDS):
        print(f"report={report_path}")
        return 1
    oracle_stage = aggregate["stages"][-1]
    if not record_beta_oracle_artifact_binding(
            aggregate, oracle_stage, sandbox_dll, artifact_hash,
            built_dll=args.built_dll.resolve()):
        save()
        print(f"report={report_path}")
        return 1
    save()
    match = re.search(r"report json:\s*(.+)",
                      oracle_stage.get("output_tail", ""))
    oracle_trace: Path | None = None
    if match:
        try:
            replay_report = json.loads(
                Path(match.group(1).strip()).read_text(encoding="utf-8"))
            trace_value = replay_report.get("trace_path")
            oracle_trace = Path(trace_value) if trace_value else None
        except (OSError, ValueError):
            oracle_trace = None
    if not oracle_trace or not oracle_trace.is_file():
        aggregate["failures"].append("normal-replay-oracle-trace-missing")
        save()
        print(f"report={report_path}")
        return 1
    oracle_validation = validate_replay_oracle_trace(
        oracle_trace, args.replay_round,
        required_frames=REPLAY_ORACLE_REQUIRED_FRAMES,
        required_rounds=2, logical_start=oracle_window_start)
    aggregate["stages"].append({
        "name": "validate-normal-replay-oracle",
        "logical_frame_end_exclusive": oracle_window_end,
        **oracle_validation,
    })
    if not oracle_validation["ok"]:
        aggregate["failures"].append("normal-replay-oracle-incomplete")
        save()
        print(f"report={report_path}")
        return 1
    if not run_stage("trusted-golden-trace", [
            sys.executable,
            str(REPO / "tools" / "rollback_golden_trace.py"),
            "--manifest", str(args.trusted_golden_manifest),
            "--case", args.trusted_golden_case,
            "--trace", str(oracle_trace),
            "--replay", str(args.replay_file),
        ], 120):
        print(f"report={report_path}")
        return 1
    try:
        args.replay_oracle_trace = oracle_trace
        args.replay_oracle_producer_artifact_sha256 = artifact_hash
        args.replay_random_seed_arg = replay_oracle_random_seed(oracle_trace)
        args.replay_round_start_frames_arg = None
        prepare_replay_input(args)
    except (OSError, ValueError, KeyError) as exc:
        aggregate["failures"].append(
            f"normal-replay-startup-metadata:{exc}")
        save()
        print(f"report={report_path}")
        return 1
    save()

    live_dir = report_path.parent / f"{report_path.stem}-live"
    live_dir.mkdir(parents=True, exist_ok=True)
    common = [
        sys.executable, str(Path(__file__).resolve()),
        "--mode", "stock-online-local-lab", "--clean-start",
        "--gameplay-transport", STEAM_BETA_TRANSPORT,
        "--input-source", "replay",
        "--built-dll", str(BUILT_DLL),
        "--candidate-manifest", str(args.candidate_manifest),
        "--replay-file", str(args.replay_original_file),
        "--replay-oracle-trace", str(oracle_trace),
        "--replay-oracle-producer-artifact-sha256", artifact_hash,
        "--replay-random-seed", hex(args.replay_random_seed),
        "--replay-round-start-frames", ",".join(
            str(value) for value in args.replay_round_start_frames),
        "--require-round-rearm",
        "--expected-artifact-sha256", artifact_hash,
        "--rollback-window", str(args.rollback_window),
        "--input-delay", str(args.input_delay),
    ]
    if args.expected_schema_id is not None:
        common.extend([
            "--expected-schema-id", hex(args.expected_schema_id),
        ])
    for name, profile, seconds, require_oracle, round_seconds \
            in BETA_LIVE_CASES:
        child_report = live_dir / f"{name}.json"
        command = build_beta_live_case_command(
            common, profile, seconds, require_oracle, round_seconds,
            child_report)
        if not run_stage(name, command, 1200):
            print(f"report={report_path}")
            return 1
        try:
            child = json.loads(child_report.read_text(encoding="utf-8"))
        except (OSError, ValueError):
            child = {}
        if not child.get("ok"):
            aggregate["failures"].append(f"live-report:{name}")
            save()
            print(f"report={report_path}")
            return 1

    try:
        manual = json.loads(
            args.manual_attach_report.read_text(encoding="utf-8"))
    except (OSError, ValueError):
        manual = {}
    runner_hash = sha256_file(Path(__file__).resolve())
    manual_hash = manual.get("evidence_identity", {}).get(
        "deployed_dll", {}).get("sha256")
    manual_failures = validate_manual_attach_certification(
        manual, artifact_hash, runner_hash,
        STEAM_BETA_TRANSPORT, "native")
    manual_ok = not manual_failures
    aggregate["stages"].append({
        "name": "manual-attach-certification",
        "report": str(args.manual_attach_report),
        "artifact_sha256": manual_hash,
        "runner_sha256": manual.get("evidence_identity", {}).get(
            "runner", {}).get("sha256"),
        "failures": manual_failures,
        "ok": manual_ok,
    })
    if not manual_ok:
        aggregate["failures"].append("manual-attach-certification-mismatch")
        save()
        print(f"report={report_path}")
        return 1

    strict_command = strict_replay_seek_command()
    if not run_stage("strict-replay-final-artifact", strict_command, 1200):
        print(f"report={report_path}")
        return 1
    if sha256_file(DEPLOYED_DLL) != artifact_hash:
        aggregate["failures"].append("artifact-changed-during-gate")
    aggregate["ok"] = beta_release_pass_allowed(
        aggregate["classification"], aggregate["stages"],
        aggregate["failures"])
    aggregate["verdict"] = "pass" if aggregate["ok"] else "incomplete"
    save()
    print(f"report={report_path}")
    print("PASS" if aggregate["ok"] else "INCOMPLETE")
    return 0 if aggregate["ok"] else 1


def local_child_evidence_failures(
        report: dict[str, Any], artifact_hash: str, runner_hash: str,
        input_source: str, require_acceptance: bool = True) -> list[str]:
    failures: list[str] = []
    if report.get("ok") is not True:
        failures.append("child-result")
    if require_acceptance and report.get("acceptance_eligible") is not True:
        failures.append("child-not-acceptance-eligible")
    if report.get("gameplay_transport") != STEAM_BETA_TRANSPORT:
        failures.append("child-transport")
    if report.get("input_source") != input_source:
        failures.append("child-input-source")
    if require_acceptance:
        failures.extend(steam_client_evidence_failures(report))
    else:
        recovery = report.get("recovery_evidence", {})
        if recovery.get("ok") is not True:
            failures.append("child-recovery-evidence")
        failures.extend(steam_client_evidence_failures({
            "clients": recovery.get("pre_loss_clients", {}),
        }))
    identity = report.get("evidence_identity", {})
    for key in ("built_dll", "deployed_dll", "sandbox_deployed_dll"):
        if str(identity.get(key, {}).get("sha256") or "").lower() \
                != artifact_hash:
            failures.append(f"child-{key}-hash")
    if str(identity.get("runner", {}).get("sha256") or "").lower() \
            != runner_hash:
        failures.append("child-runner-hash")
    return failures


def replay_corpus_local_coverage_failures(
        report: dict[str, Any], artifact_hash: str,
        runner_hash: str, expected_replays: list[dict[str, Any]],
        minimum_content_pairs: int = 4) -> list[str]:
    failures: list[str] = []
    if report.get("ok") is not True \
            or report.get("verdict") != "pass":
        failures.append("corpus-result")
    if report.get("transport") != STEAM_BETA_TRANSPORT \
            or report.get("input_source") != "replay":
        failures.append("corpus-transport-input")
    if str(report.get("artifact_sha256") or "").lower() != artifact_hash:
        failures.append("corpus-artifact")
    if str(report.get("runner_sha256") or "").lower() != runner_hash:
        failures.append("corpus-runner")
    cases_value = report.get("cases", {})
    cases = list(cases_value.values()) \
        if isinstance(cases_value, dict) else list(cases_value or [])
    expected_hashes = {
        str(entry.get("sha256") or "").lower()
        for entry in expected_replays
        if valid_sha256_text(str(entry.get("sha256") or "").lower())
    }
    observed_hashes = {
        str(case.get("replay_sha256") or "").lower()
        for case in cases
        if valid_sha256_text(str(case.get("replay_sha256") or "").lower())
    }
    if len(expected_hashes) != len(expected_replays):
        failures.append("corpus-candidate-inventory-invalid")
    if observed_hashes != expected_hashes:
        failures.append("corpus-candidate-inventory-mismatch")
    report_manifest_entries = report.get("manifest", {}).get("entries", [])
    report_manifest_hashes = {
        str(entry.get("sha256") or "").lower()
        for entry in report_manifest_entries
        if isinstance(entry, dict)
        and valid_sha256_text(str(entry.get("sha256") or "").lower())
    }
    if report_manifest_hashes != expected_hashes:
        failures.append("corpus-report-manifest-mismatch")
    passed = [case for case in cases if case.get("status") == "pass"]
    if len(passed) != len(expected_hashes):
        failures.append(
            f"corpus-passed={len(passed)}/{len(expected_hashes)}")
    content_pairs = {
        (
            _trace_int(case.get("metadata", {}).get("left_style_id"), -1),
            _trace_int(case.get("metadata", {}).get("right_style_id"), -1),
            _trace_int(case.get("metadata", {}).get("stage_index"), -1),
        )
        for case in passed
    }
    content_pairs = {
        pair for pair in content_pairs if min(pair) >= 0
    }
    if len(content_pairs) < minimum_content_pairs:
        failures.append(
            f"corpus-content-pairs={len(content_pairs)}/"
            f"{minimum_content_pairs}")
    unsupported = [
        case for case in cases
        if case.get("status") == "unsupported-missing-content"
    ]
    if unsupported:
        failures.append(f"corpus-unsupported-content={len(unsupported)}")
    return failures


def expected_full_local_stage_names(soak_matches: int) -> list[str]:
    names = [
        "deploy-immutable-candidate",
        "fresh-gekko-on-off-presubmit",
        "runner-selftest",
        "policy-lint",
        "golden-negative-controls",
        "physical-manifest-negative-controls",
        "normal-replay-differential-oracle",
        "trusted-golden-matrix",
        "steam-sandboxie-exact-artifact-smoke",
    ]
    names.extend(f"matrix:{case[0]}" for case in BETA_MATRIX_CASES)
    names.extend([
        "replay-corpus-candidate",
        "replay-corpus-content-coverage",
        "native-two-controller-attach",
    ])
    for phase in ("bootstrap", "active", "round-transition"):
        for role in ("host", "sandbox"):
            names.extend([
                f"recovery:{phase}:{role}",
                f"recovery-followup:{phase}:{role}",
            ])
    names.extend([
        "recovery:sandbox-steam-exit",
        "recovery-followup:sandbox-steam-exit",
        "bounded-worker-stall:host",
        "bounded-worker-stall:sandbox",
    ])
    names.extend(
        f"lifecycle-soak:match-{index:03d}"
        for index in range(1, soak_matches + 1))
    names.extend([
        "lifecycle-soak-summary",
        "continuous-session-soak",
        "strict-replay-final-candidate",
    ])
    return names


def local_qualification_stage_inventory(
        stages: object,
        minimum_soak_matches: int = 10) -> dict[str, Any]:
    failures: list[str] = []
    if not isinstance(stages, list) or not stages:
        return {
            "schema_version": LOCAL_STAGE_INVENTORY_SCHEMA_VERSION,
            "ok": False,
            "failures": ["local-stage-inventory-empty"],
            "observed_names": [],
            "expected_names": expected_full_local_stage_names(
                minimum_soak_matches),
        }
    names = [str(stage.get("name") or "")
             if isinstance(stage, dict) else "" for stage in stages]
    if any(not name for name in names):
        failures.append("local-stage-name-missing")
    if len(set(names)) != len(names):
        failures.append("local-stage-name-duplicate")
    soak_pattern = re.compile(r"^lifecycle-soak:match-(\d{3,})$")
    soak_numbers = [
        int(match.group(1))
        for name in names
        if (match := soak_pattern.fullmatch(name))
    ]
    if len(soak_numbers) < minimum_soak_matches:
        failures.append(
            f"local-stage-lifecycle-matches="
            f"{len(soak_numbers)}/{minimum_soak_matches}")
    if soak_numbers != list(range(1, len(soak_numbers) + 1)):
        failures.append("local-stage-lifecycle-sequence")
    expected = expected_full_local_stage_names(len(soak_numbers))
    if names != expected:
        failures.append("local-stage-inventory-exact-order")
    failed_names = [
        names[index] or f"index-{index}"
        for index, stage in enumerate(stages)
        if not isinstance(stage, dict) or stage.get("ok") is not True
    ]
    if failed_names:
        failures.append("local-stage-result-failed")
    return {
        "schema_version": LOCAL_STAGE_INVENTORY_SCHEMA_VERSION,
        "ok": not failures,
        "failures": failures,
        "observed_names": names,
        "expected_names": expected,
        "soak_matches": len(soak_numbers),
        "minimum_soak_matches": minimum_soak_matches,
        "failed_names": failed_names,
    }


def local_beta_gate(args: argparse.Namespace) -> int:
    report_path = args.report or (
        REPO / "reports" / "rollback_beta" /
        f"local-beta-{datetime.now():%Y%m%d-%H%M%S}.json"
    )
    smoke_only = bool(args.local_beta_smoke_only)
    aggregate: dict[str, Any] = {
        "report_schema_version": REPORT_SCHEMA_VERSION,
        "oracle_schema_version": ROLLBACK_ORACLE_SCHEMA_VERSION,
        "workflow": "local-beta-gate",
        "classification": "single-host-dual-client",
        "qualification_scope": "local-only",
        "gameplay_transport": STEAM_BETA_TRANSPORT,
        "generated_at": utc_now(),
        "ok": False,
        "verdict": "diagnostic-incomplete" if smoke_only else "incomplete",
        "smoke_only": smoke_only,
        "candidate_manifest": str(args.candidate_manifest),
        "artifact": {},
        "stages": [],
        "failures": [],
    }

    def save() -> None:
        atomic_json(report_path, aggregate)

    def run_stage(
            name: str, command: list[str], timeout: float,
            child_report: Path | None = None,
            child_input_source: str | None = None,
            require_acceptance: bool = True) -> bool:
        started = time.time()
        try:
            result = subprocess.run(
                command, cwd=REPO, text=True,
                stdout=subprocess.PIPE, stderr=subprocess.STDOUT,
                timeout=timeout, check=False,
            )
            stage: dict[str, Any] = {
                "name": name,
                "command": command,
                "returncode": result.returncode,
                "seconds": time.time() - started,
                "output_tail": (result.stdout or "")[-12000:],
                "ok": result.returncode == 0,
            }
            if name in {
                    "runner-selftest", "policy-lint",
                    "golden-negative-controls",
                    "physical-manifest-negative-controls"}:
                stage["evidence_policy"] = "release-rerun"
            if child_report is None:
                discovered_report = parse_report_path_from_output(
                    result.stdout or "")
                if discovered_report is not None:
                    stage["report"] = str(discovered_report)
                    stage["report_sha256"] = sha256_file(discovered_report)
        except (OSError, subprocess.TimeoutExpired) as exc:
            stage = {
                "name": name,
                "command": command,
                "seconds": time.time() - started,
                "error": f"{type(exc).__name__}:{exc}",
                "ok": False,
            }
        if stage["ok"] and child_report is not None:
            try:
                child = json.loads(
                    child_report.read_text(encoding="utf-8"))
            except (OSError, ValueError) as exc:
                child = {}
                stage["child_report_error"] = (
                    f"{type(exc).__name__}:{exc}")
            evidence_failures = (
                local_child_evidence_failures(
                    child, artifact_hash, runner_hash,
                    child_input_source, require_acceptance)
                if child_input_source is not None
                else ([] if isinstance(child, dict)
                      and child.get("ok") is True
                      else ["child-result"])
            )
            stage["child_report"] = str(child_report)
            stage["child_report_sha256"] = (
                sha256_file(child_report)
                if child_report.is_file() else None)
            stage["evidence_failures"] = evidence_failures
            stage["ok"] = not evidence_failures
        aggregate["stages"].append(stage)
        if not stage["ok"]:
            aggregate["failures"].append(f"stage:{name}")
        save()
        return bool(stage["ok"])

    candidate_dll = args.built_dll.resolve()
    try:
        candidate = load_candidate_manifest(
            args.candidate_manifest, candidate_dll,
            require_clean=not smoke_only, args=args)
    except RuntimeError as exc:
        aggregate["failures"].append(f"candidate:{exc}")
        save()
        print(f"report={report_path}")
        return 2
    artifact_hash = str(candidate["dll"]["sha256"]).lower()
    runner_hash = str(candidate["runner"]["sha256"]).lower()
    aggregate["candidate"] = candidate
    aggregate["candidate_manifest_sha256"] = sha256_file(
        args.candidate_manifest)
    if not candidate_dll.is_file():
        aggregate["failures"].append("candidate-dll-missing")
    if not args.replay_file or not args.replay_file.is_file():
        aggregate["failures"].append("missing-local-beta-replay")
    if not smoke_only and (
            not args.manual_attach_report
            or not args.manual_attach_report.is_file()):
        aggregate["failures"].append("missing-native-attach-report")
    if not args.local_beta_replay_corpus.is_dir():
        aggregate["failures"].append("missing-replay-corpus")
    if aggregate["failures"]:
        save()
        print(f"report={report_path}")
        return 2

    kill_clients()
    sandbox_dll = sandbox_deployed_dll(
        args.sandbox_root, args.sandbox_box)
    try:
        deploy_selected_candidate(candidate_dll, sandbox_dll)
        require_deployment_preflight(sandbox_dll, candidate_dll)
        require_expected_artifact_hash(
            sandbox_dll, artifact_hash, built_dll=candidate_dll)
    except (OSError, RuntimeError) as exc:
        aggregate["failures"].append(f"deployment-preflight:{exc}")
        save()
        print(f"report={report_path}")
        return 1
    aggregate["artifact"] = capture_evidence_identity(
        sandbox_dll, candidate_dll)
    aggregate["stages"].append({
        "name": "deploy-immutable-candidate",
        "source": str(candidate_dll),
        "artifact_sha256": artifact_hash,
        "runner_sha256": runner_hash,
        "evidence_policy": "recomputed-current-dll-hashes",
        "ok": True,
    })
    save()

    presubmit_report = report_path.with_name(
        report_path.stem + "-presubmit.json")
    presubmit_root = report_path.with_name(
        report_path.stem + "-presubmit-builds")
    if not run_stage("fresh-gekko-on-off-presubmit", [
            sys.executable,
            str(REPO / "tools" / "rollback_presubmit_matrix.py"),
            "--build-root", str(presubmit_root),
            "--report", str(presubmit_report),
        ], 3600, presubmit_report):
        print(f"report={report_path}")
        return 1
    for name, command in (
        ("runner-selftest", [
            sys.executable, str(Path(__file__).resolve()), "--selftest"]),
        ("policy-lint", [
            sys.executable, str(Path(__file__).resolve()), "--policy-lint"]),
        ("golden-negative-controls", [
            sys.executable,
            str(REPO / "tools" / "rollback_golden_trace.py"),
            "--selftest"]),
        ("physical-manifest-negative-controls", [
            sys.executable,
            str(REPO / "tools" / "rollback_two_machine_qualification.py"),
            "--selftest"]),
    ):
        if not run_stage(name, command, 300):
            print(f"report={report_path}")
            return 1

    oracle_dir = report_path.with_name(report_path.stem + "-oracle")
    if not run_stage(
            "normal-replay-differential-oracle",
            normal_replay_oracle_command(
                args.replay_file, oracle_dir, candidate_dll),
            NORMAL_REPLAY_ORACLE_STAGE_TIMEOUT_SECONDS):
        print(f"report={report_path}")
        return 1
    oracle_stage = aggregate["stages"][-1]
    if not record_beta_oracle_artifact_binding(
            aggregate, oracle_stage, sandbox_dll, artifact_hash,
            built_dll=candidate_dll):
        save()
        print(f"report={report_path}")
        return 1
    save()
    match = re.search(
        r"report json:\s*(.+)", oracle_stage.get("output_tail", ""))
    oracle_trace: Path | None = None
    if match:
        try:
            oracle_report = json.loads(
                Path(match.group(1).strip()).read_text(encoding="utf-8"))
            oracle_trace_value = oracle_report.get("trace_path")
            oracle_trace = Path(oracle_trace_value) \
                if oracle_trace_value else None
        except (OSError, ValueError):
            oracle_trace = None
    if not oracle_trace or not oracle_trace.is_file():
        aggregate["failures"].append("normal-oracle-trace-missing")
        save()
        print(f"report={report_path}")
        return 1
    golden_matrix_dir = report_path.with_name(
        report_path.stem + "-trusted-golden-matrix")
    golden_matrix_report = (
        golden_matrix_dir / "rollback_golden_matrix.json")
    if not run_stage("trusted-golden-matrix", [
            sys.executable,
            str(REPO / "tools" / "rollback_golden_matrix.py"),
            "--manifest", str(args.trusted_golden_manifest),
            "--candidate-dll", str(candidate_dll),
            "--deployed-dll", str(DEPLOYED_DLL),
            "--report-dir", str(golden_matrix_dir),
        ], 3600):
        print(f"report={report_path}")
        return 1
    try:
        golden_matrix = json.loads(
            golden_matrix_report.read_text(encoding="utf-8"))
    except (OSError, ValueError):
        golden_matrix = {}
    golden_stage = aggregate["stages"][-1]
    golden_failures: list[str] = []
    if golden_matrix.get("gate_ok") is not True:
        golden_failures.append("trusted-golden-matrix-gate")
    if golden_matrix.get("coverage_complete") is not True:
        golden_failures.append("trusted-golden-matrix-coverage")
    if str(golden_matrix.get(
            "candidate_dll_sha256") or "").lower() != artifact_hash:
        golden_failures.append("trusted-golden-matrix-artifact")
    if golden_matrix.get("manifest_sha256") != sha256_file(
            args.trusted_golden_manifest):
        golden_failures.append("trusted-golden-matrix-manifest")
    golden_stage["child_report"] = str(golden_matrix_report)
    golden_stage["child_report_sha256"] = (
        sha256_file(golden_matrix_report)
        if golden_matrix_report.is_file() else None)
    golden_stage["required_case_ids"] = golden_matrix.get(
        "required_case_ids", [])
    golden_stage["selected_case_ids"] = golden_matrix.get(
        "selected_case_ids", [])
    golden_stage["evidence_failures"] = golden_failures
    golden_stage["ok"] = not golden_failures
    if golden_failures:
        aggregate["failures"].append("stage:trusted-golden-matrix")
        save()
        print(f"report={report_path}")
        return 1
    replay_args = argparse.Namespace(**vars(args))
    replay_args.replay_oracle_trace = oracle_trace
    replay_args.replay_oracle_producer_artifact_sha256 = artifact_hash
    replay_args.replay_random_seed_arg = replay_oracle_random_seed(
        oracle_trace)
    replay_args.replay_round_start_frames_arg = None
    try:
        prepare_replay_input(replay_args)
    except (OSError, ValueError, KeyError) as exc:
        aggregate["failures"].append(f"replay-metadata:{exc}")
        save()
        print(f"report={report_path}")
        return 1

    evidence_dir = report_path.with_name(report_path.stem + "-evidence")
    evidence_dir.mkdir(parents=True, exist_ok=True)
    common = [
        sys.executable, str(Path(__file__).resolve()),
        "--mode", "stock-online-local-lab",
        "--gameplay-transport", STEAM_BETA_TRANSPORT,
        "--input-source", "replay",
        "--built-dll", str(candidate_dll),
        "--candidate-manifest", str(args.candidate_manifest),
        "--beta-config-profile", str(args.beta_config_profile),
        "--replay-file", str(replay_args.replay_original_file),
        "--replay-oracle-trace", str(oracle_trace),
        "--replay-oracle-producer-artifact-sha256", artifact_hash,
        "--replay-random-seed", hex(replay_args.replay_random_seed),
        "--replay-round-start-frames", ",".join(
            str(value) for value
            in replay_args.replay_round_start_frames),
        "--rollback-window", str(args.rollback_window),
        "--input-delay", str(args.input_delay),
        "--rollback-depth", str(args.rollback_depth),
        "--trusted-golden-manifest",
        str(args.trusted_golden_manifest),
        "--local-beta-replay-corpus",
        str(args.local_beta_replay_corpus),
        "--local-beta-soak-seconds",
        str(args.local_beta_soak_seconds),
        "--local-beta-soak-min-matches",
        str(args.local_beta_soak_min_matches),
        "--native-controller-phase-seconds",
        str(args.native_controller_phase_seconds),
        "--require-round-rearm",
        "--expected-artifact-sha256", artifact_hash,
        "--expected-runner-sha256", runner_hash,
    ]
    if args.expected_schema_id is not None:
        common.extend([
            "--expected-schema-id", hex(args.expected_schema_id)])

    smoke_report = evidence_dir / "steam-sandboxie-smoke.json"
    smoke_command = build_beta_live_case_command(
        [*common, "--clean-start"], "clean_0ms", 30, True, 3,
        smoke_report)
    if not run_stage(
            "steam-sandboxie-exact-artifact-smoke", smoke_command, 1200,
            smoke_report, "replay"):
        print(f"report={report_path}")
        return 1
    if smoke_only:
        strict_command = strict_replay_seek_command(built_dll=candidate_dll)
        run_stage("strict-replay-smoke-candidate", strict_command, 1200)
        aggregate["ok"] = not aggregate["failures"]
        aggregate["verdict"] = (
            "local-smoke-passed-not-qualified"
            if aggregate["ok"] else "diagnostic-incomplete")
        aggregate["relay_classification"] = "not-wan-relay-qualified"
        save()
        print(f"report={report_path}")
        print("SMOKE PASS (NOT QUALIFIED)" if aggregate["ok"]
              else "INCOMPLETE")
        return 0 if aggregate["ok"] else 1

    for index, (name, profile, seconds, seed, require_oracle) \
            in enumerate(BETA_MATRIX_CASES):
        child_report = evidence_dir / f"matrix-{name}.json"
        child_common = [
            *common,
            "--clean-start" if index == 0 else "--no-launch",
            "--fault-seed", hex(seed),
        ]
        command = build_beta_live_case_command(
            child_common, profile, seconds, require_oracle, 10,
            child_report)
        if not run_stage(
                f"matrix:{name}", command, 1500,
                child_report, "replay"):
            print(f"report={report_path}")
            return 1

    corpus_report = evidence_dir / "replay-corpus-candidate.json"
    corpus_command = [
        sys.executable, str(Path(__file__).resolve()),
        "--replay-corpus", str(args.local_beta_replay_corpus),
        "--replay-corpus-gate",
        "--replay-corpus-require-state-oracle",
        "--gameplay-transport", STEAM_BETA_TRANSPORT,
        "--input-source", "replay",
        "--built-dll", str(candidate_dll),
        "--candidate-manifest", str(args.candidate_manifest),
        "--beta-config-profile", str(args.beta_config_profile),
        "--rollback-window", str(args.rollback_window),
        "--input-delay", str(args.input_delay),
        "--rollback-depth", str(args.rollback_depth),
        "--trusted-golden-manifest",
        str(args.trusted_golden_manifest),
        "--local-beta-replay-corpus",
        str(args.local_beta_replay_corpus),
        "--local-beta-soak-seconds",
        str(args.local_beta_soak_seconds),
        "--local-beta-soak-min-matches",
        str(args.local_beta_soak_min_matches),
        "--native-controller-phase-seconds",
        str(args.native_controller_phase_seconds),
        "--expected-artifact-sha256", artifact_hash,
        "--expected-runner-sha256", runner_hash,
        "--report", str(corpus_report),
    ]
    if not run_stage("replay-corpus-candidate", corpus_command, 21600):
        print(f"report={report_path}")
        return 1
    try:
        corpus_value = json.loads(
            corpus_report.read_text(encoding="utf-8"))
    except (OSError, ValueError):
        corpus_value = {}
    corpus_failures = replay_corpus_local_coverage_failures(
        corpus_value, artifact_hash, runner_hash,
        list(candidate.get("qualification_contract", {}).get(
            "replay_corpus", {}).get("replays", [])))
    aggregate["stages"].append({
        "name": "replay-corpus-content-coverage",
        "aggregate_children": ["replay-corpus-candidate"],
        "failures": corpus_failures,
        "ok": not corpus_failures,
    })
    if corpus_failures:
        aggregate["failures"].append("replay-corpus-content-coverage")
        save()
        print(f"report={report_path}")
        return 1

    try:
        manual = json.loads(
            args.manual_attach_report.read_text(encoding="utf-8"))
    except (OSError, ValueError):
        manual = {}
    manual_failures = validate_manual_attach_certification(
        manual, artifact_hash, runner_hash,
        STEAM_BETA_TRANSPORT, "native")
    aggregate["stages"].append({
        "name": "native-two-controller-attach",
        "report": str(args.manual_attach_report),
        "report_sha256": sha256_file(args.manual_attach_report),
        "failures": manual_failures,
        "ok": not manual_failures,
    })
    if manual_failures:
        aggregate["failures"].append("native-two-controller-attach")
        save()
        print(f"report={report_path}")
        return 1

    recovery_common = [
        sys.executable, str(Path(__file__).resolve()),
        "--mode", "stock-online-local-lab",
        "--gameplay-transport", STEAM_BETA_TRANSPORT,
        "--input-source", "fixture",
        "--built-dll", str(candidate_dll),
        "--candidate-manifest", str(args.candidate_manifest),
        "--beta-config-profile", str(args.beta_config_profile),
        "--rollback-window", str(args.rollback_window),
        "--input-delay", str(args.input_delay),
        "--rollback-depth", str(args.rollback_depth),
        "--trusted-golden-manifest",
        str(args.trusted_golden_manifest),
        "--local-beta-replay-corpus",
        str(args.local_beta_replay_corpus),
        "--local-beta-soak-seconds",
        str(args.local_beta_soak_seconds),
        "--local-beta-soak-min-matches",
        str(args.local_beta_soak_min_matches),
        "--native-controller-phase-seconds",
        str(args.native_controller_phase_seconds),
        "--expected-artifact-sha256", artifact_hash,
        "--expected-runner-sha256", runner_hash,
        "--profile", "wifi_50ms_jitter",
        "--active-seconds", "120",
        "--shutdown-clients",
    ]
    recovery_cases = [
        (role, phase)
        for phase in ("bootstrap", "active", "round-transition")
        for role in ("host", "sandbox")
    ]
    for role, phase in recovery_cases:
        child_report = evidence_dir / f"recovery-{phase}-{role}.json"
        command = [
            *recovery_common, "--clean-start",
            "--test-peer-loss-role", role,
            "--test-peer-loss-phase", phase,
            "--report", str(child_report),
        ]
        if not run_stage(
                f"recovery:{phase}:{role}", command, 1200,
                child_report, "fixture", require_acceptance=False):
            print(f"report={report_path}")
            return 1
        followup_report = evidence_dir / (
            f"recovery-{phase}-{role}-new-lobby.json")
        followup = build_beta_live_case_command(
            [*common, "--clean-start"], "clean_0ms", 30, True, 3,
            followup_report)
        if not run_stage(
                f"recovery-followup:{phase}:{role}", followup, 1200,
                followup_report, "replay"):
            print(f"report={report_path}")
            return 1

    steam_exit_report = evidence_dir / "recovery-sandbox-steam-exit.json"
    if not run_stage(
            "recovery:sandbox-steam-exit",
            [*recovery_common, "--clean-start",
             "--test-sandbox-steam-exit",
             "--report", str(steam_exit_report)],
            1200, steam_exit_report, "fixture",
            require_acceptance=False):
        print(f"report={report_path}")
        return 1
    steam_followup_report = evidence_dir / (
        "recovery-sandbox-steam-exit-new-lobby.json")
    steam_followup = build_beta_live_case_command(
        [*common, "--clean-start"], "clean_0ms", 30, True, 3,
        steam_followup_report)
    if not run_stage(
            "recovery-followup:sandbox-steam-exit", steam_followup,
            1200, steam_followup_report, "replay"):
        print(f"report={report_path}")
        return 1

    for stall_role in ("host", "sandbox"):
        stall_report = evidence_dir / f"worker-stall-{stall_role}.json"
        stall_command = build_beta_live_case_command(
            [*common, "--clean-start",
             "--test-worker-stall-role", stall_role,
             "--test-worker-stall-after-ms", "15000",
             "--test-worker-stall-duration-ms", "250"],
            "wifi_50ms_jitter", 120, True, 10, stall_report)
        if not run_stage(
                f"bounded-worker-stall:{stall_role}",
                stall_command, 1500,
                stall_report, "replay"):
            print(f"report={report_path}")
            return 1

    soak_started = time.monotonic()
    soak_children: list[dict[str, Any]] = []
    soak_index = 0
    while time.monotonic() - soak_started < args.local_beta_soak_seconds \
            or soak_index < args.local_beta_soak_min_matches:
        soak_index += 1
        child_report = evidence_dir / f"soak-match-{soak_index:03d}.json"
        launch_flag = "--clean-start" if soak_index == 1 else "--no-launch"
        soak_command = build_beta_live_case_command(
            [*common, launch_flag, "--fault-seed",
             hex(0x5C6B6000 + soak_index)],
            "wifi_50ms_jitter", 120, True, 10, child_report)
        if not run_stage(
                f"lifecycle-soak:match-{soak_index:03d}",
                soak_command, 1500,
                child_report, "replay"):
            print(f"report={report_path}")
            return 1
        child = json.loads(child_report.read_text(encoding="utf-8"))
        child_clients = child.get("clients", {})
        soak_children.append({
            "report": str(child_report),
            "sha256": sha256_file(child_report),
            "pids": [
                _trace_int(child_clients.get(role, {}).get("pid"))
                for role in ("host", "sandbox")
            ],
            "process_create_times": [
                child_clients.get(role, {}).get("process_create_time")
                for role in ("host", "sandbox")
            ],
            "session_epochs": [
                _trace_int(child_clients.get(
                    role, {}).get("status", {}).get("session_epoch"))
                for role in ("host", "sandbox")
            ],
            "steam_lobby_id": _trace_int(child_clients.get(
                "host", {}).get("status", {}).get("steam_lobby_id")),
        })
    stable_processes = (
        len({tuple(child["pids"]) for child in soak_children}) == 1
        and len({
            tuple(child["process_create_times"])
            for child in soak_children
        }) == 1
    )
    unique_lobbies = {
        child["steam_lobby_id"] for child in soak_children
        if child["steam_lobby_id"] != 0
    }
    session_epochs_valid = all(
        len(set(child["session_epochs"])) == 1
        and child["session_epochs"][0] != 0
        for child in soak_children)
    soak_ok = (
        soak_index >= args.local_beta_soak_min_matches
        and time.monotonic() - soak_started
            >= args.local_beta_soak_seconds
        and stable_processes
        and session_epochs_valid
        and len(unique_lobbies) == soak_index
    )
    aggregate["stages"].append({
        "name": "lifecycle-soak-summary",
        "classification": "same-process-lobby-match-lifecycle",
        "elapsed_seconds": time.monotonic() - soak_started,
        "completed_matches": soak_index,
        "required_seconds": args.local_beta_soak_seconds,
        "required_matches": args.local_beta_soak_min_matches,
        "stable_processes": stable_processes,
        "session_epochs_valid": session_epochs_valid,
        "unique_lobbies": len(unique_lobbies),
        "children": soak_children,
        "ok": soak_ok,
    })
    if not aggregate["stages"][-1]["ok"]:
        aggregate["failures"].append("lifecycle-soak")
        save()
        print(f"report={report_path}")
        return 1

    continuous_report = evidence_dir / "continuous-session-soak.json"
    continuous_command = [
        sys.executable, str(Path(__file__).resolve()),
        "--mode", "stock-online-local-lab",
        "--gameplay-transport", STEAM_BETA_TRANSPORT,
        "--input-source", "fixture",
        "--built-dll", str(candidate_dll),
        "--candidate-manifest", str(args.candidate_manifest),
        "--beta-config-profile", str(args.beta_config_profile),
        "--expected-artifact-sha256", artifact_hash,
        "--expected-runner-sha256", runner_hash,
        "--rollback-window", str(args.rollback_window),
        "--input-delay", str(args.input_delay),
        "--rollback-depth", str(args.rollback_depth),
        "--trusted-golden-manifest",
        str(args.trusted_golden_manifest),
        "--local-beta-replay-corpus",
        str(args.local_beta_replay_corpus),
        "--local-beta-soak-seconds",
        str(args.local_beta_soak_seconds),
        "--local-beta-soak-min-matches",
        str(args.local_beta_soak_min_matches),
        "--native-controller-phase-seconds",
        str(args.native_controller_phase_seconds),
        "--rounds-to-win", "255",
        "--profile", "wifi_50ms_jitter",
        "--active-seconds", str(int(args.local_beta_soak_seconds)),
        "--required-round-active-seconds", "10",
        "--require-presentation-checkpoint",
        "--clean-start", "--shutdown-clients",
        "--report", str(continuous_report),
    ]
    if not run_stage(
            "continuous-session-soak", continuous_command,
            args.local_beta_soak_seconds + 1800,
            continuous_report, "fixture"):
        print(f"report={report_path}")
        return 1
    try:
        continuous_value = json.loads(
            continuous_report.read_text(encoding="utf-8"))
    except (OSError, ValueError):
        continuous_value = {}
    continuous_resource_failures = \
        continuous_resource_telemetry_failures(
            continuous_value, args.local_beta_soak_seconds)
    continuous_stage = aggregate["stages"][-1]
    continuous_stage["resource_telemetry_failures"] = \
        continuous_resource_failures
    continuous_stage["resource_telemetry"] = \
        continuous_value.get("resource_telemetry")
    continuous_stage["ok"] = not continuous_resource_failures
    if continuous_resource_failures:
        aggregate["failures"].append(
            "continuous-session-soak-resource-telemetry")
        save()
        print(f"report={report_path}")
        return 1

    strict_command = strict_replay_seek_command(built_dll=candidate_dll)
    if not run_stage("strict-replay-final-candidate", strict_command, 1200):
        print(f"report={report_path}")
        return 1
    if sha256_file(candidate_dll) != artifact_hash \
            or sha256_file(DEPLOYED_DLL) != artifact_hash:
        aggregate["failures"].append("candidate-changed-during-gate")
    aggregate["stage_inventory"] = local_qualification_stage_inventory(
        aggregate["stages"], minimum_soak_matches=10)
    if not aggregate["stage_inventory"]["ok"]:
        aggregate["failures"].extend(
            aggregate["stage_inventory"]["failures"])
    aggregate["relay_observation"] = {
        "classification": "same-machine-steam-route",
        "wan_or_relay_qualified": False,
        "note": "Bilateral steam_using_relay is recorded per child; local "
                "direct P2P is valid local evidence only.",
    }
    aggregate["evidence_digest_root"] = local_evidence_digest_root(
        aggregate["stages"])
    aggregate["ok"] = not aggregate["failures"]
    aggregate["verdict"] = (
        "single-host-dual-client-qualified"
        if aggregate["ok"] else "incomplete")
    save()
    print(f"report={report_path}")
    print("SINGLE-HOST DUAL-CLIENT QUALIFIED"
          if aggregate["ok"] else "INCOMPLETE")
    return 0 if aggregate["ok"] else 1


def local_evidence_digest_root(
        stages: list[dict[str, Any]]) -> dict[str, Any]:
    entries: list[dict[str, Any]] = []
    for stage_index, stage in enumerate(stages):
        entry: dict[str, Any] = {
            "index": stage_index,
            "name": stage.get("name"),
            "ok": stage.get("ok"),
        }
        if stage.get("command") is not None:
            entry["command"] = stage.get("command")
        for source_key in (
                "artifact_sha256", "child_report_sha256",
                "report_sha256"):
            if stage.get(source_key):
                entry[source_key] = stage[source_key]
        children = [
            {
                "report": child.get("report"),
                "sha256": child.get("sha256"),
            }
            for child in stage.get("children", [])
            if child.get("report") or child.get("sha256")
        ]
        if children:
            entry["children"] = children
        entries.append(entry)
    payload = json.dumps(
        entries, sort_keys=True, separators=(",", ":"),
        ensure_ascii=False).encode("utf-8")
    return {
        "algorithm": "sha256-json-v1",
        "entry_count": len(entries),
        "sha256": hashlib.sha256(payload).hexdigest(),
        "entries": entries,
    }


def local_stage_semantic_failures(
        stage: dict[str, Any], child: dict[str, Any], artifact_hash: str,
        runner_hash: str, candidate: dict[str, Any]) -> list[str]:
    """Reapply the authoritative contract for each persisted local stage."""
    stage_name = str(stage.get("name") or "")
    if stage_name == "fresh-gekko-on-off-presubmit":
        failures: list[str] = []
        cases = child.get("cases")
        if child.get("schema_version") != 1 or child.get("ok") is not True \
                or not isinstance(cases, list) or len(cases) != 2:
            return ["presubmit-report-contract"]
        by_mode = {case.get("gekko_enabled"): case for case in cases
                   if isinstance(case, dict)}
        if set(by_mode) != {True, False}:
            failures.append("presubmit-gekko-matrix")
        for enabled, minimum in ((True, 65), (False, 60)):
            case = by_mode.get(enabled, {})
            case_stages = case.get("stages")
            if case.get("ok") is not True \
                    or int(case.get("test_count", 0)) < minimum \
                    or not isinstance(case_stages, list) \
                    or [item.get("name") for item in case_stages] \
                        != ["configure", "build", "ctest"] \
                    or any(item.get("ok") is not True
                           for item in case_stages):
                failures.append(f"presubmit-case:{int(enabled)}")
        return failures
    if stage_name == "trusted-golden-matrix":
        contract = candidate.get("qualification_contract", {})
        return [item for item, ok in (
            ("golden-gate", child.get("gate_ok") is True),
            ("golden-coverage", child.get("coverage_complete") is True),
            ("golden-artifact", str(child.get(
                "candidate_dll_sha256") or "").lower() == artifact_hash),
            ("golden-manifest", child.get("manifest_sha256") == contract.get(
                "trusted_golden_manifest", {}).get("sha256")),
        ) if not ok]
    if stage_name == "replay-corpus-candidate":
        return replay_corpus_local_coverage_failures(
            child, artifact_hash, runner_hash,
            list(candidate.get("qualification_contract", {}).get(
                "replay_corpus", {}).get("replays", [])))
    if stage_name == "native-two-controller-attach":
        return validate_manual_attach_certification(
            child, artifact_hash, runner_hash,
            STEAM_BETA_TRANSPORT, "native")
    if stage_name in {
            "normal-replay-differential-oracle",
            "strict-replay-final-candidate"}:
        failures = []
        if child.get("final_passed") is not True \
                or child.get("exit_code") != 0 \
                or child.get("analyzer_exit_code") != 0:
            failures.append("replay-result")
        helper_hash = next((str(item.get("sha256") or "").lower()
                            for item in candidate.get(
                                "qualification_contract", {}).get(
                                    "runner_helpers", [])
                            if Path(str(item.get("path") or "")).name
                            == "replay_seek_test_run.py"), "")
        artifact_evidence = child.get("artifact_evidence")
        if not isinstance(artifact_evidence, dict) \
                or str(artifact_evidence.get(
                    "dll_sha256") or "").lower() != artifact_hash \
                or str(artifact_evidence.get(
                    "replay_runner_sha256") or "").lower() != helper_hash:
            failures.append("replay-candidate-binding")
        if stage_name == "normal-replay-differential-oracle":
            identity = stage.get("artifact_identity_after")
            if stage.get("artifact_sha256") != artifact_hash \
                    or not isinstance(identity, dict) \
                    or any(str(identity.get(key, {}).get(
                        "sha256") or "").lower() != artifact_hash
                           for key in ("built_dll", "deployed_dll",
                                       "sandbox_deployed_dll")) \
                    or str(identity.get("runner", {}).get(
                        "sha256") or "").lower() != runner_hash:
                failures.append("oracle-stage-candidate-binding")
        trace_path = Path(str(child.get("trace_path") or ""))
        if not trace_path.is_file():
            failures.append("replay-trace-missing")
        else:
            command = [sys.executable, str(
                REPO / "tools" / "replay_seek_test_analyze.py"),
                str(trace_path)]
            if stage_name == "strict-replay-final-candidate":
                command.extend([
                    "--require-tests", "--run-id", str(child.get("run_id")),
                    "--min-resume-tick-rate", "58",
                    "--resume-tick-window", "120",
                    "--max-seek-validation-seconds", "0.5", "--strict",
                ])
            try:
                result = subprocess.run(
                    command, cwd=REPO, stdout=subprocess.PIPE,
                    stderr=subprocess.STDOUT, text=True, timeout=300,
                    check=False)
                if result.returncode != 0:
                    failures.append("replay-trace-semantic-revalidation")
            except (OSError, subprocess.TimeoutExpired):
                failures.append("replay-trace-semantic-revalidation")
        if stage_name == "strict-replay-final-candidate":
            summary = child.get("summary", {})
            if summary.get("passed") is not True \
                    or int(summary.get("passed_cases", 0)) != 4 \
                    or int(summary.get("failed_cases", -1)) != 0 \
                    or child.get("failed_case_labels"):
                failures.append("strict-replay-cases")
        return failures
    replay_acceptance = (
        stage_name == "steam-sandboxie-exact-artifact-smoke"
        or stage_name.startswith("matrix:")
        or stage_name.startswith("recovery-followup:")
        or stage_name.startswith("bounded-worker-stall:")
        or stage_name.startswith("lifecycle-soak:match-"))
    fixture_recovery = stage_name.startswith("recovery:")
    if replay_acceptance:
        return local_child_evidence_failures(
            child, artifact_hash, runner_hash, "replay", True)
    if fixture_recovery:
        return local_child_evidence_failures(
            child, artifact_hash, runner_hash, "fixture", False)
    if stage_name == "continuous-session-soak":
        failures = local_child_evidence_failures(
            child, artifact_hash, runner_hash, "fixture", True)
        minimum = float(candidate.get("qualification_contract", {}).get(
            "local_beta_soak_seconds", 3600.0))
        failures.extend(continuous_resource_telemetry_failures(child, minimum))
        return failures
    return ["unknown-local-stage-report-contract"]


def beta_release_bundle_failures(
        candidate: dict[str, Any],
        candidate_manifest_sha256: str | None,
        local: dict[str, Any],
        physical: dict[str, Any],
        audit_local_paths: bool = True,
        physical_manifest_path: Path | None = None) -> list[str]:
    failures: list[str] = []
    artifact_hash = str(candidate.get(
        "dll", {}).get("sha256") or "").lower()
    runner_hash = str(candidate.get(
        "runner", {}).get("sha256") or "").lower()
    if local.get("report_schema_version") != REPORT_SCHEMA_VERSION:
        failures.append("local-qualification-report-schema")
    if local.get("workflow") != "local-beta-gate" \
            or local.get("verdict") \
                != "single-host-dual-client-qualified" \
            or local.get("ok") is not True:
        failures.append("local-qualification-verdict")
    if local.get("gameplay_transport") != STEAM_BETA_TRANSPORT:
        failures.append("local-qualification-transport")
    inventory = local_qualification_stage_inventory(
        local.get("stages"), minimum_soak_matches=10)
    if not inventory["ok"] \
            or local.get("stage_inventory") != inventory:
        failures.append("local-qualification-stage-inventory")
    local_candidate = local.get("candidate", {})
    if str(local_candidate.get(
            "dll", {}).get("sha256") or "").lower() != artifact_hash:
        failures.append("local-qualification-artifact")
    if str(local_candidate.get(
            "runner", {}).get("sha256") or "").lower() != runner_hash:
        failures.append("local-qualification-runner")
    if local.get("candidate_manifest_sha256") != \
            candidate_manifest_sha256:
        failures.append("local-candidate-manifest")
    if local_candidate != candidate:
        failures.append("local-candidate-identity")
    expected_root = local_evidence_digest_root(
        list(local.get("stages", [])))
    observed_root = local.get("evidence_digest_root", {})
    if observed_root != expected_root:
        failures.append("local-evidence-digest-root")
    evidence_paths: set[Path] = set()
    evidence_optional = {
        "deploy-immutable-candidate", "runner-selftest", "policy-lint",
        "golden-negative-controls", "physical-manifest-negative-controls",
    }
    for stage in local.get("stages", []):
        stage_name = str(stage.get("name") or "unknown")
        evidence_path_value = stage.get(
            "child_report", stage.get("report"))
        evidence_hash = stage.get(
            "child_report_sha256", stage.get("report_sha256"))
        if not evidence_path_value or not evidence_hash:
            if stage_name == "replay-corpus-content-coverage":
                parent = next((item for item in local.get("stages", [])
                               if item.get("name")
                               == "replay-corpus-candidate"), None)
                if not isinstance(parent, dict) \
                        or stage.get("aggregate_children") \
                            != ["replay-corpus-candidate"] \
                        or stage.get("ok") is not True \
                        or stage.get("failures"):
                    failures.append(
                        "local-stage-aggregate:replay-corpus-content-coverage")
                continue
            if stage_name == "lifecycle-soak-summary":
                children = stage.get("children")
                valid_children = isinstance(children, list) and children
                for child in (children if isinstance(children, list) else []):
                    child_path = Path(str(child.get("report", "")))
                    child_hash = str(child.get("sha256", ""))
                    if audit_local_paths and (not child_path.is_file()
                            or sha256_file(child_path) != child_hash):
                        valid_children = False
                recomputed = bool(valid_children) \
                    and int(stage.get("completed_matches", -1)) \
                        == len(children) \
                    and len(children) >= int(stage.get(
                        "required_matches", 0)) \
                    and float(stage.get("elapsed_seconds", -1)) >= float(
                        stage.get("required_seconds", 0)) \
                    and stage.get("stable_processes") is True \
                    and stage.get("session_epochs_valid") is True \
                    and int(stage.get("unique_lobbies", -1)) == len(children)
                if stage.get("ok") is not recomputed:
                    failures.append(
                        "local-stage-aggregate:lifecycle-soak-summary")
                continue
            if stage_name not in evidence_optional:
                failures.append(f"local-stage-evidence-missing:{stage_name}")
            elif stage.get("evidence_policy") != "release-rerun" \
                    and stage_name != "deploy-immutable-candidate":
                failures.append(f"local-stage-rerun-policy:{stage_name}")
            continue
        evidence_path = Path(str(evidence_path_value)).resolve()
        if evidence_path in evidence_paths:
            failures.append(f"local-stage-evidence-duplicate:{stage_name}")
        evidence_paths.add(evidence_path)
        if audit_local_paths:
            evidence_path = Path(str(evidence_path_value))
            if not evidence_path.is_file() \
                    or sha256_file(evidence_path) != evidence_hash:
                failures.append(
                    f"local-stage-evidence:"
                    f"{stage_name}")
                continue
            try:
                child = json.loads(evidence_path.read_text(encoding="utf-8"))
            except (OSError, UnicodeError, json.JSONDecodeError) as exc:
                failures.append(f"local-stage-evidence-json:{stage_name}:{exc}")
                continue
            semantic_failures = (
                local_stage_semantic_failures(
                    stage, child, artifact_hash, runner_hash, candidate)
                if isinstance(child, dict) else ["child-not-object"])
            child_ok = not semantic_failures
            if semantic_failures:
                failures.extend(
                    f"local-stage-semantic:{stage_name}:{item}"
                    for item in semantic_failures)
            if stage.get("ok") is not child_ok:
                failures.append(f"local-stage-result-recompute:{stage_name}")
    if physical.get("schema_version") != 5 \
            or physical.get("classification") \
                != "physical-two-machine-release-qualification":
        failures.append("physical-qualification-schema")
    else:
        physical_candidate = physical.get("candidate", {})
        if str(physical_candidate.get(
                "candidate_dll_sha256") or "").lower() != artifact_hash:
            failures.append("physical-qualification-artifact")
        if physical_candidate.get("source_commit") != \
                candidate.get("git", {}).get("commit"):
            failures.append("physical-qualification-source-commit")
        if physical_candidate.get("protocol_version") != \
                candidate.get("protocol_version"):
            failures.append("physical-qualification-protocol-version")
        if physical_candidate.get("snapshot_version") != \
                candidate.get("snapshot_version"):
            failures.append("physical-qualification-snapshot-version")
        expected_profile = str(candidate.get(
            "qualification_contract", {}).get(
                "beta_config_profile", {}).get("sha256") or "").lower()
        machine_profiles = {
            str(physical.get("machines", {}).get(role, {}).get(
                "profile_sha256") or "").lower()
            for role in ("host", "guest")
        }
        if machine_profiles != {expected_profile}:
            failures.append("physical-qualification-profile")
        if audit_local_paths and physical_manifest_path is not None:
            try:
                from rollback_two_machine_qualification import \
                    validation_failures as physical_validation_failures
                failures.extend(
                    "physical-revalidation:" + item
                    for item in physical_validation_failures(
                        physical, physical_manifest_path.resolve().parent))
            except (ImportError, OSError, ValueError) as exc:
                failures.append(f"physical-revalidation:{exc}")
    return failures


def beta_release_gate(args: argparse.Namespace) -> int:
    report_path = args.report or (
        REPO / "reports" / "rollback_beta" /
        f"beta-release-{datetime.now():%Y%m%d-%H%M%S}.json"
    )
    failures: list[str] = []
    release_reruns = (
        ("runner-selftest", [sys.executable, str(Path(__file__).resolve()),
                             "--selftest"]),
        ("policy-lint", [sys.executable, str(Path(__file__).resolve()),
                         "--policy-lint"]),
        ("golden-negative-controls", [
            sys.executable, str(REPO / "tools" / "rollback_golden_trace.py"),
            "--selftest"]),
        ("physical-runner-negative-controls", [
            sys.executable,
            str(REPO / "tools" / "rollback_physical_case_run.py"),
            "--selftest"]),
        ("physical-manifest-negative-controls", [
            sys.executable,
            str(REPO / "tools" / "rollback_two_machine_qualification.py"),
            "--selftest"]),
    )
    for name, command in release_reruns:
        try:
            result = subprocess.run(
                command, cwd=REPO, stdout=subprocess.PIPE,
                stderr=subprocess.STDOUT, text=True, timeout=600,
                check=False)
            if result.returncode != 0:
                failures.append(f"release-rerun:{name}")
        except (OSError, subprocess.TimeoutExpired):
            failures.append(f"release-rerun:{name}")
    candidate_dll = args.built_dll.resolve()
    try:
        candidate = load_candidate_manifest(
            args.candidate_manifest, candidate_dll,
            require_clean=True, args=args)
    except RuntimeError as exc:
        candidate = {}
        failures.append(f"candidate:{exc}")
    if candidate:
        expected_artifact = str(candidate.get(
            "dll", {}).get("sha256") or "").lower()
        for label, path in (("built", candidate_dll),
                            ("deployed", DEPLOYED_DLL)):
            if not path.is_file() or sha256_file(path) != expected_artifact:
                failures.append(f"release-current-{label}-dll")
    local: dict[str, Any] = {}
    if not args.local_qualification_report \
            or not args.local_qualification_report.is_file():
        failures.append("missing-local-qualification-report")
    else:
        try:
            local = json.loads(args.local_qualification_report.read_text(
                encoding="utf-8"))
        except (OSError, ValueError):
            failures.append("invalid-local-qualification-report")
    physical: dict[str, Any] = {}
    if not args.release_qualification_manifest \
            or not args.release_qualification_manifest.is_file():
        failures.append("missing-two-machine-release-qualification")
    else:
        try:
            result = subprocess.run([
                sys.executable,
                str(REPO / "tools" /
                    "rollback_two_machine_qualification.py"),
                "--validate", str(args.release_qualification_manifest),
            ], cwd=REPO, capture_output=True, text=True,
                timeout=300, check=False)
            if result.returncode != 0:
                failures.append("physical-qualification-invalid")
            physical = json.loads(
                args.release_qualification_manifest.read_text(
                    encoding="utf-8"))
        except (OSError, ValueError, subprocess.TimeoutExpired):
            failures.append("physical-qualification-unreadable")
    if candidate and local and physical:
        failures.extend(beta_release_bundle_failures(
            candidate,
            sha256_file(args.candidate_manifest)
                if args.candidate_manifest.is_file() else None,
            local, physical,
            physical_manifest_path=args.release_qualification_manifest))
    aggregate = {
        "report_schema_version": REPORT_SCHEMA_VERSION,
        "oracle_schema_version": ROLLBACK_ORACLE_SCHEMA_VERSION,
        "workflow": "beta-release-gate",
        "classification": "physical-release-qualification",
        "generated_at": utc_now(),
        "gameplay_transport": STEAM_BETA_TRANSPORT,
        "candidate": candidate,
        "local_qualification_report": (
            str(args.local_qualification_report)
            if args.local_qualification_report else None),
        "local_qualification_sha256": (
            sha256_file(args.local_qualification_report)
            if args.local_qualification_report
            and args.local_qualification_report.is_file() else None),
        "physical_qualification_manifest": (
            str(args.release_qualification_manifest)
            if args.release_qualification_manifest else None),
        "physical_qualification_sha256": (
            sha256_file(args.release_qualification_manifest)
            if args.release_qualification_manifest
            and args.release_qualification_manifest.is_file() else None),
        "failures": failures,
        "ok": not failures,
        "verdict": "beta-release-qualified"
            if not failures else "incomplete",
    }
    atomic_json(report_path, aggregate)
    print(f"report={report_path}")
    print("BETA RELEASE QUALIFIED" if not failures else "INCOMPLETE")
    return 0 if not failures else 1


def parse_args() -> argparse.Namespace:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--mode", choices=("stock-online-local-lab",
                                           "stock-online-attach"),
                        default="stock-online-local-lab")
    parser.add_argument("--profile", choices=ROLLBACK_NETWORK_PROFILES,
                        default="clean_0ms")
    parser.add_argument(
        "--gameplay-transport", choices=("direct-udp", "steam-p2p"),
        default="direct-udp",
        help="Horse gameplay transport; steam-p2p uses SC6's existing Steam "
             "session and does not require port forwarding")
    parser.add_argument(
        "--built-dll", type=Path, default=BUILT_DLL,
        help="reviewed HorseMod DLL that must match both deployments")
    parser.add_argument(
        "--input-source", choices=ROLLBACK_INPUT_SOURCES,
        help="explicit gameplay input authority; replay is inferred only "
             "when --replay-file is present for backward compatibility")
    parser.add_argument(
        "--native-controller-preflight", action="store_true",
        help="require timed host-only and Sandboxie-only controller phases")
    parser.add_argument(
        "--native-controller-phase-seconds", type=float, default=5.0,
        help="seconds per neutral/host-only/Sandboxie-only native-input phase")
    parser.add_argument(
        "--candidate-manifest", type=Path,
        help="immutable manifest binding the reviewed DLL, runner, source, "
             "transport, protocol, and snapshot versions")
    parser.add_argument(
        "--beta-config-profile", type=Path,
        default=DEFAULT_BETA_CONFIG_PROFILE,
        help="exact rollback_beta.ini profile frozen into the candidate "
             "qualification contract")
    parser.add_argument(
        "--physical-case-matrix", type=Path,
        default=DEFAULT_PHYSICAL_CASE_MATRIX,
        help="candidate-bound immutable physical case/profile policy")
    parser.add_argument(
        "--write-candidate-manifest", type=Path,
        help="write an immutable candidate manifest and exit")
    parser.add_argument(
        "--require-clean-candidate", action="store_true",
        help="reject a candidate manifest captured from a dirty worktree")
    parser.add_argument("--left-character", type=int,
                        help="explicit UI character code; replay runs derive it")
    parser.add_argument("--right-character", type=int,
                        help="explicit UI character code; replay runs derive it")
    parser.add_argument("--stage", type=lambda value: int(value, 0),
                        help="explicit native stage index; replay runs derive it")
    parser.add_argument("--rounds-to-win", type=int,
                        help="stock BattleRule rounds needed to win; replay "
                             "runs derive it from verified metadata")
    parser.add_argument("--rollback-window", type=int, default=12)
    parser.add_argument("--input-delay", type=int, default=1)
    parser.add_argument("--correction-start", type=int,
                        help="submission frame for correction; replay runs "
                             "derive it without skipping source frames")
    parser.add_argument("--hold-updates", type=int, default=6)
    parser.add_argument("--replay-file", type=Path,
                        help="use one replay round as the production Gekko "
                             "input source")
    parser.add_argument("--replay-round", type=int, default=0)
    parser.add_argument("--replay-start-frame", type=int)
    parser.add_argument("--replay-random-seed",
                        dest="replay_random_seed_arg",
                        type=lambda value: int(value, 0),
                        help="verified native replay BattleRule.RandomSeed")
    parser.add_argument("--replay-round-start-frames",
                        dest="replay_round_start_frames_arg",
                        help="comma-separated oracle-proven source origins")
    parser.add_argument("--replay-swap-players", action="store_true")
    parser.add_argument(
        "--test-unlock-replay-selection", action="store_true",
        help="test-only: permit the exact replay-selected characters through "
             "the local-lab preflight; stock selection, asset loading, and "
             "spawned fighter identity remain mandatory")
    parser.add_argument(
        "--test-unlock-required-local-role", choices=("host", "sandbox"),
        help="add strict proof that this client's stock availability filter "
             "was missing and appended at least one exact replay-selected "
             "DLC character")
    parser.add_argument(
        "--test-unlock-required-local-steam-id",
        type=lambda value: int(value, 0),
        help="SteamID64 expected for --test-unlock-required-local-role; "
             "accepted as decimal or 0x-prefixed hexadecimal")
    parser.add_argument(
        "--replay-corpus", type=Path,
        help="write a read-only SHA-keyed inventory for every .bin replay in "
             "this directory; no game or live test is launched")
    parser.add_argument(
        "--replay-corpus-gate", action="store_true",
        help="generate a same-artifact normal input oracle and run one clean "
             "two-client compatibility case through a rollback correction "
             "and one rearm for every replay in --replay-corpus")
    parser.add_argument(
        "--replay-corpus-require-state-oracle", action="store_true",
        help="also require full normal-versus-online state-oracle equality; "
             "this remains separate from the default compatibility corpus")
    parser.add_argument(
        "--replay-corpus-resume", action="store_true",
        help="resume an interrupted corpus gate only when replay, runner, "
             "artifact, and manifest identities still match")
    parser.add_argument(
        "--replay-corpus-limit", type=int,
        help="run only the first N SHA-manifest cases as a diagnostic; this "
             "can return success but can never produce a corpus pass verdict")
    parser.add_argument("--replay-trace-compare", action="store_true",
                        help="emit corrected-frame semantics for exact "
                             "consumed-input and two-peer correction evidence")
    parser.add_argument(
        "--replay-deep-trace-diagnostics", action="store_true",
        help="add high-volume primitive animation, collision, stage-wind, "
             "and RNG localization evidence; requires "
             "--replay-trace-compare and is not needed for beta acceptance")
    parser.add_argument(
        "--frame-input-log-trace-only", action="store_true",
        help="request the validated FrameInputLog tick-control detour without "
             "the high-volume animation, collision, and MoveVM lifecycle "
             "probes; requires --replay-trace-compare")
    parser.add_argument(
        "--replay-input-compare-only", action="store_true",
        help="with --replay-trace-compare, require exact replay inputs and "
             "two-peer correction evidence without claiming full "
             "normal-versus-online state equality")
    parser.add_argument("--replay-oracle-trace", type=Path,
                        help="normal replay JSONL oracle used to build the "
                             "exact low-32 consumed-input sidecar; state is "
                             "compared with --replay-trace-compare unless "
                             "--replay-input-compare-only is selected")
    parser.add_argument(
        "--replay-oracle-producer-artifact-sha256",
        help="SHA-256 of the DLL that produced the normal input trace; "
             "reported separately from the consuming candidate")
    parser.add_argument(
        "--trusted-golden-manifest",
        type=Path,
        default=DEFAULT_TRUSTED_GOLDEN_MANIFEST,
        help="immutable trusted normal-replay manifest required by "
             "--beta-release-gate")
    parser.add_argument(
        "--trusted-golden-case",
        default=DEFAULT_TRUSTED_GOLDEN_CASE,
        help="trusted golden case ID required by --beta-release-gate")
    parser.add_argument("--rollback-depth", type=int, default=6,
                        help="target replay correction depth; depth plus "
                             "input delay must fit the rollback window")
    parser.add_argument(
        "--test-forced-rollback-depth", type=int,
        choices=(0, 1, 6, 11), default=0,
        help="diagnostic-only: force this rollback depth on every owned "
             "update; rejected by release qualification")
    parser.add_argument(
        "--test-every-advance-save-policy", action="store_true",
        help="diagnostic-only: negotiate EveryAdvance without forced "
             "rollback for identical-input save-policy A/B; rejected by "
             "local and release qualification")
    parser.add_argument("--fault-seed", type=lambda value: int(value, 0),
                        default=0x5C6B5001)
    parser.add_argument(
        "--test-worker-stall-role", choices=("host", "sandbox"),
        help="test-only: apply one bounded transport worker stall to this "
             "role and require observed recovery telemetry")
    parser.add_argument(
        "--test-worker-stall-after-ms", type=int, default=15000,
        help="worker uptime before the test-only stall")
    parser.add_argument(
        "--test-worker-stall-duration-ms", type=int, default=250,
        help="bounded worker stall duration (1..1000 ms)")
    parser.add_argument(
        "--test-peer-loss-role", choices=("host", "sandbox"),
        help="test-only: terminate this exact gameplay process")
    parser.add_argument(
        "--test-peer-loss-phase",
        choices=("bootstrap", "active", "round-transition"),
        help="lifecycle point for --test-peer-loss-role")
    parser.add_argument(
        "--test-sandbox-steam-exit", action="store_true",
        help="test-only: terminate Sandboxie Steam during active rollback; "
             "this simulates session loss without changing account state")
    parser.add_argument("--expected-build-id", type=lambda value: int(value, 0),
                        default=DEFAULT_BUILD_ID)
    parser.add_argument("--expected-schema-id", type=lambda value: int(value, 0),
                        help="optional exact schema assertion; normally read "
                             "from both freshly loaded DLLs")
    parser.add_argument("--expected-artifact-sha256",
                        help="require the built, host, and Sandboxie DLLs to "
                             "match this reviewed SHA-256 before launch")
    parser.add_argument("--expected-runner-sha256",
                        help="require this exact reviewed runner SHA-256 "
                             "before any live or corpus work")
    parser.add_argument("--sandbox-root", type=Path,
                        default=DEFAULT_SANDBOX_ROOT)
    parser.add_argument("--sandbox-box", default=DEFAULT_SANDBOX_BOX)
    parser.add_argument("--host-bind-address", default="127.0.0.1")
    parser.add_argument("--host-peer-address", default="127.0.0.1")
    parser.add_argument("--host-port", type=udp_port, default=HOST_PORT)
    parser.add_argument("--sandbox-bind-address", default="127.0.0.1")
    parser.add_argument("--sandbox-peer-address", default="127.0.0.1")
    parser.add_argument("--sandbox-port", type=udp_port, default=SANDBOX_PORT)
    parser.add_argument("--sandboxie", type=Path, default=DEFAULT_SANDBOXIE)
    parser.add_argument("--steam", type=Path, default=DEFAULT_STEAM)
    parser.add_argument("--sandbox-steam-timeout", type=float, default=120.0)
    parser.add_argument("--clean-start", action="store_true")
    parser.add_argument("--no-launch", action="store_true")
    parser.add_argument("--shutdown-clients", action="store_true")
    parser.add_argument("--setup-only", action="store_true",
                        help="enter and rate-check a stock match without "
                             "arming rollback production")
    parser.add_argument(
        "--callback-inventory-diagnostic", action="store_true",
        help="capture both native callback collections before hooks and "
             "stop without rollback ownership; local-lab automates setup")
    parser.add_argument(
        "--native-correction-diagnostic", action="store_true",
        help="run only the native Save/Load/rollback/convergence gate; "
             "presentation acceptance and round rearm are excluded")
    parser.add_argument("--launch-lead-seconds", type=float, default=20.0)
    parser.add_argument("--launch-timeout", type=float, default=240.0)
    parser.add_argument("--setup-timeout", type=float, default=600.0)
    parser.add_argument("--active-seconds", type=float, default=120.0)
    parser.add_argument(
        "--min-confirmed-frame", type=int, default=0,
        help="require each client to pair-confirm at least this logical frame")
    parser.add_argument("--required-round-active-seconds", type=float,
                        default=0.0,
                        help="minimum stable Active evidence required in each "
                             "of the first two rollback rounds")
    parser.add_argument("--require-round-rearm", action="store_true",
                        help="require both clients to hand off and rearm the "
                              "next stock replay round")
    parser.add_argument(
        "--require-match-complete", action="store_true",
        help="continue after the active-time minimum until both clients "
             "produce matching, fully attributed stock match-complete "
             "terminal evidence")
    parser.add_argument(
        "--match-complete-timeout", type=float, default=900.0,
        help="wall-clock budget armed only after both clients first enter "
             "active rollback when --require-match-complete is set")
    parser.add_argument(
        "--require-presentation-checkpoint", action="store_true",
        help="require an exact pair-confirmed fixture-convergence camera "
             "checkpoint from both clients")
    parser.add_argument(
        "--require-palette-writer-observation", action="store_true",
        help="require each client to observe at least one native palette "
             "checkpoint writer call and zero writer-observer failures")
    # A canonical cleanup has measured about 37 seconds from ExitBattle to
    # MainMenu after a slow 29-second TitleScene online reset.  Fifty seconds
    # leaves room for that stock work plus the required five stable Main Menu
    # seconds without bypassing EmulateTitleDecide.  This is only a failure
    # deadline; successful cleanup returns immediately.
    parser.add_argument("--cleanup-timeout", type=float, default=50.0)
    parser.add_argument("--report", type=Path)
    parser.add_argument("--selftest", action="store_true")
    parser.add_argument(
        "--policy-lint", action="store_true",
        help="run source ownership and static implementation policy checks; "
             "these results are separate from release correctness evidence")
    parser.add_argument("--beta-release-gate", action="store_true",
                        help="run the non-skippable build, hermetic, oracle, "
                             "live, strict-replay, and manual-attach gate")
    parser.add_argument(
        "--local-beta-gate", action="store_true",
        help="run the artifact-bound one-machine Steam qualification gate")
    parser.add_argument(
        "--local-beta-smoke-only", action="store_true",
        help="run presubmit, exact-artifact Steam smoke, and strict replay "
             "without claiming local beta qualification")
    parser.add_argument(
        "--local-beta-replay-corpus", type=Path,
        default=REPO / "ReplayExample",
        help="14-replay corpus consumed by the full local beta gate")
    parser.add_argument(
        "--local-beta-soak-seconds", type=float, default=3600.0,
        help="minimum persistent same-process soak duration")
    parser.add_argument(
        "--local-beta-soak-min-matches", type=int, default=10,
        help="minimum successful matches/rematches in the persistent soak")
    parser.add_argument("--manual-attach-report", type=Path,
                        help="passing stock-online-attach report for the same "
                             "DLL; required by the full --local-beta-gate")
    parser.add_argument(
        "--local-qualification-report", type=Path,
        help="immutable single-host-dual-client-qualified report consumed by "
             "--beta-release-gate")
    parser.add_argument(
        "--release-qualification-manifest", type=Path,
        help="passing physical two-machine qualification manifest bound to "
             "the same DLL; required by --beta-release-gate")
    return parser.parse_args()


def _main(args: argparse.Namespace) -> int:
    for path_attribute in (
            "built_dll", "candidate_manifest", "write_candidate_manifest",
            "beta_config_profile", "physical_case_matrix",
            "report", "replay_file", "replay_corpus",
            "replay_oracle_trace", "trusted_golden_manifest",
            "manual_attach_report", "local_qualification_report",
            "release_qualification_manifest"):
        value = getattr(args, path_attribute, None)
        if isinstance(value, Path):
            setattr(args, path_attribute, value.resolve())
    if args.write_candidate_manifest:
        incompatible = (
            args.selftest or args.policy_lint or args.beta_release_gate
            or args.local_beta_gate or args.replay_corpus is not None
            or args.report is not None
        )
        if incompatible:
            print("--write-candidate-manifest is a standalone mode",
                  file=sys.stderr)
            return 2
        return write_candidate_manifest(
            args.write_candidate_manifest, args.built_dll.resolve(), args)
    if args.selftest and args.policy_lint:
        print("--selftest and --policy-lint are mutually exclusive",
              file=sys.stderr)
        return 2
    if args.selftest:
        return selftest()
    if args.policy_lint:
        return selftest(policy_only=True)
    if args.candidate_manifest:
        try:
            candidate = load_candidate_manifest(
                args.candidate_manifest, args.built_dll.resolve(),
                require_clean=args.require_clean_candidate, args=args)
        except RuntimeError as exc:
            print(str(exc), file=sys.stderr)
            return 2
        candidate_artifact = str(candidate["dll"]["sha256"]).lower()
        candidate_runner = str(candidate["runner"]["sha256"]).lower()
        if args.expected_artifact_sha256 \
                and args.expected_artifact_sha256.lower() \
                != candidate_artifact:
            print("candidate-expected-artifact-mismatch", file=sys.stderr)
            return 2
        if args.expected_runner_sha256 \
                and args.expected_runner_sha256.lower() != candidate_runner:
            print("candidate-expected-runner-mismatch", file=sys.stderr)
            return 2
        args.expected_artifact_sha256 = candidate_artifact
        args.expected_runner_sha256 = candidate_runner
    if args.beta_release_gate or args.local_beta_gate:
        if args.gameplay_transport != STEAM_BETA_TRANSPORT:
            print("beta gates require --gameplay-transport steam-p2p",
                  file=sys.stderr)
            return 2
        if not args.candidate_manifest:
            print("beta gates require --candidate-manifest",
                  file=sys.stderr)
            return 2
    if args.local_beta_smoke_only and not args.local_beta_gate:
        print("--local-beta-smoke-only requires --local-beta-gate",
              file=sys.stderr)
        return 2
    if args.local_beta_gate:
        if args.local_beta_smoke_only:
            if args.local_beta_soak_seconds < 0 \
                    or args.local_beta_soak_min_matches < 1:
                print("local beta smoke diagnostics require nonnegative "
                      "soak seconds and at least one match", file=sys.stderr)
                return 2
        elif args.local_beta_soak_seconds < 3600 \
                or args.local_beta_soak_min_matches < 10:
            print("full local beta qualification requires at least 3600 "
                  "soak seconds and ten completed matches", file=sys.stderr)
            return 2
    source_failures = input_source_argument_failures(args)
    if source_failures:
        print("input-source:" + ",".join(source_failures),
              file=sys.stderr)
        return 2
    if args.native_controller_preflight and (
            selected_input_source(args) != "native"
            or args.mode != "stock-online-attach"
            or not sys.stdin.isatty()
            or args.native_controller_phase_seconds < 3.0
            or args.active_seconds
                < args.native_controller_phase_seconds * 3.0 + 10.0):
        print("--native-controller-preflight requires native "
              "stock-online-attach in an interactive terminal, phases of "
              "at least 3 seconds, and "
              "enough active time for all phases plus ten seconds",
              file=sys.stderr)
        return 2
    if bool(args.test_peer_loss_role) != bool(args.test_peer_loss_phase):
        print("--test-peer-loss-role and --test-peer-loss-phase must be "
              "provided together", file=sys.stderr)
        return 2
    if args.test_peer_loss_role and (
            args.mode != "stock-online-local-lab"
            or args.test_sandbox_steam_exit
            or args.native_controller_preflight
            or not args.shutdown_clients):
        print("peer-loss stress requires local-lab, --shutdown-clients, "
              "and cannot be combined with Steam-exit/controller preflight",
              file=sys.stderr)
        return 2
    if args.test_sandbox_steam_exit and (
            args.mode != "stock-online-local-lab"
            or args.native_controller_preflight
            or not args.shutdown_clients):
        print("Sandbox Steam-exit stress requires local-lab and "
              "--shutdown-clients", file=sys.stderr)
        return 2
    if args.test_worker_stall_role and (
            args.test_worker_stall_after_ms <= 0
            or not 1 <= args.test_worker_stall_duration_ms <= 1000
            or args.test_peer_loss_role
            or args.test_sandbox_steam_exit):
        print("worker-stall stress requires positive timing (duration "
              "1..1000 ms) and cannot be combined with loss tests",
              file=sys.stderr)
        return 2
    if args.expected_runner_sha256:
        observed_runner = sha256_file(Path(__file__).resolve())
        runner_failure = expected_runner_sha256_failure(
            args.expected_runner_sha256, observed_runner)
        if runner_failure:
            print(runner_failure, file=sys.stderr)
            return 2
    if args.replay_corpus is not None:
        incompatible = (
            args.beta_release_gate
            or args.local_beta_gate
            or args.replay_file is not None
            or args.setup_only
            or args.callback_inventory_diagnostic
            or args.native_correction_diagnostic
            or args.test_unlock_replay_selection
        )
        if incompatible:
            print("--replay-corpus is a standalone read-only inventory mode",
                  file=sys.stderr)
            return 2
        if args.replay_corpus_resume and not args.replay_corpus_gate:
            print("--replay-corpus-resume requires --replay-corpus-gate",
                  file=sys.stderr)
            return 2
        if args.replay_corpus_limit is not None \
                and not args.replay_corpus_gate:
            print("--replay-corpus-limit requires --replay-corpus-gate",
                  file=sys.stderr)
            return 2
        if args.replay_corpus_require_state_oracle \
                and not args.replay_corpus_gate:
            print("--replay-corpus-require-state-oracle requires "
                  "--replay-corpus-gate", file=sys.stderr)
            return 2
        if args.require_palette_writer_observation \
                and not args.replay_corpus_gate:
            print("--require-palette-writer-observation with "
                  "--replay-corpus requires --replay-corpus-gate",
                  file=sys.stderr)
            return 2
        return replay_corpus_gate(args) if args.replay_corpus_gate \
            else replay_corpus_inventory(args)
    if args.replay_corpus_gate or args.replay_corpus_resume \
            or args.replay_corpus_require_state_oracle \
            or args.replay_corpus_limit is not None:
        print("--replay-corpus-gate requires --replay-corpus",
              file=sys.stderr)
        return 2
    if args.replay_input_compare_only and (
            not args.replay_trace_compare
            or args.replay_oracle_trace is None):
        print("--replay-input-compare-only requires "
              "--replay-trace-compare and --replay-oracle-trace",
              file=sys.stderr)
        return 2
    if args.frame_input_log_trace_only and not args.replay_trace_compare:
        print("--frame-input-log-trace-only requires "
              "--replay-trace-compare", file=sys.stderr)
        return 2
    if args.replay_deep_trace_diagnostics \
            and not args.replay_trace_compare:
        print("--replay-deep-trace-diagnostics requires "
              "--replay-trace-compare", file=sys.stderr)
        return 2
    if args.min_confirmed_frame < 0:
        print("--min-confirmed-frame must be nonnegative", file=sys.stderr)
        return 2
    if args.report and not report_evidence_paths_available(args.report):
        print(
            "report-evidence-path-exists:" + str(args.report),
            file=sys.stderr,
        )
        return 2
    if args.beta_release_gate and args.test_forced_rollback_depth:
        print("forced rollback is diagnostic evidence, not release evidence",
              file=sys.stderr)
        return 2
    if (args.beta_release_gate or args.local_beta_gate) \
            and args.test_every_advance_save_policy:
        print("EveryAdvance is diagnostic A/B evidence, not release evidence",
              file=sys.stderr)
        return 2
    if args.beta_release_gate:
        return beta_release_gate(args)
    if args.local_beta_gate:
        return local_beta_gate(args)
    if args.test_unlock_replay_selection and \
            not replay_test_selection_override_allowed(
                args.mode, args.replay_file, args.setup_only,
                args.callback_inventory_diagnostic,
                args.native_correction_diagnostic):
        print("--test-unlock-replay-selection requires a replay-driven "
              "stock-online-local-lab production run", file=sys.stderr)
        return 2
    required_unlock_role = args.test_unlock_required_local_role
    required_unlock_steam_id = args.test_unlock_required_local_steam_id
    if (required_unlock_role is None) != \
            (required_unlock_steam_id is None):
        print("--test-unlock-required-local-role and "
              "--test-unlock-required-local-steam-id must be supplied "
              "together", file=sys.stderr)
        return 2
    if required_unlock_role is not None and \
            not args.test_unlock_replay_selection:
        print("--test-unlock-required-local-role requires "
              "--test-unlock-replay-selection", file=sys.stderr)
        return 2
    if required_unlock_steam_id is not None and \
            required_unlock_steam_id <= 0:
        print("--test-unlock-required-local-steam-id must be positive",
              file=sys.stderr)
        return 2
    if args.require_presentation_checkpoint and (
            args.setup_only or args.callback_inventory_diagnostic
            or args.native_correction_diagnostic):
        print("--require-presentation-checkpoint requires a full rollback "
              "run", file=sys.stderr)
        return 2
    if args.require_match_complete and (
            args.setup_only or args.callback_inventory_diagnostic
            or args.native_correction_diagnostic
            or not args.require_round_rearm):
        print("--require-match-complete requires a full rollback run with "
              "--require-round-rearm", file=sys.stderr)
        return 2
    if args.match_complete_timeout <= 0:
        print("--match-complete-timeout must be positive", file=sys.stderr)
        return 2
    if not palette_writer_observation_mode_allowed(
            args.require_palette_writer_observation,
            args.setup_only, args.callback_inventory_diagnostic,
            args.native_correction_diagnostic):
        print("--require-palette-writer-observation requires a full "
              "rollback run", file=sys.stderr)
        return 2
    if args.callback_inventory_diagnostic and (
            args.setup_only or args.shutdown_clients
            or args.profile != "clean_0ms"
            or args.replay_file is not None
            or args.replay_oracle_trace is not None
            or args.require_round_rearm):
        print("--callback-inventory-diagnostic requires "
              "a clean stock-online run without setup-only, client "
              "shutdown, replay input/oracle, or round rearm",
              file=sys.stderr)
        return 2
    if args.native_correction_diagnostic and (
            args.callback_inventory_diagnostic or args.setup_only
            or args.profile != "clean_0ms"
            or args.replay_file is not None
            or args.replay_oracle_trace is not None
            or args.require_round_rearm
            or args.active_seconds > 20.0):
        print("--native-correction-diagnostic requires a clean automated "
              "run of at most 20 seconds without setup-only, callback "
              "inventory, replay/oracle, or round rearm",
              file=sys.stderr)
        return 2
    try:
        prepare_replay_input(args)
    except (OSError, ValueError, KeyError) as exc:
        print(f"replay-input-preflight:{exc}", file=sys.stderr)
        return 2
    try:
        configure_replay_comparison_window(args)
    except ValueError as exc:
        print(f"replay-oracle-window-preflight:{exc}", file=sys.stderr)
        return 2
    if args.replay_oracle_trace and not args.replay_oracle_trace.is_file():
        print("replay oracle trace does not exist", file=sys.stderr)
        return 2
    selected_dlc = [
        code for code, required in (
            (args.left_character_code, args.left_character_requires_dlc),
            (args.right_character_code, args.right_character_requires_dlc),
        ) if required or (code.isdecimal() and int(code) in DLC_CHARACTER_IDS)
    ]
    if selected_dlc and not args.test_unlock_replay_selection:
        print(
            "DLC characters are unavailable in the Sandboxie client: "
            + ", ".join(sorted(selected_dlc))
            + "; use --test-unlock-replay-selection only for an exact "
              "replay-driven local-lab test",
            file=sys.stderr,
        )
        return 2
    if required_unlock_role is not None:
        if not selected_dlc:
            print(
                "required replay-selection client proof has no DLC target: "
                f"role={required_unlock_role}",
                file=sys.stderr,
            )
            return 2
    sandbox_saved = sandbox_saved_root(args.sandbox_root, args.sandbox_box)
    sandbox_gameimgui_disable = sandbox_saved.parents[3] \
        / GAMEIMGUI_DISABLE.name
    roots = [HOST_SAVED, sandbox_saved]
    # The outer main() finally owns this guard before any marker is changed,
    # client is launched, barrier is created, or request is published.
    arm_live_run_cleanup(roots)
    stale_lease_recovered = begin_marker_lease([
        RUNTIME_ORACLE_ENABLED,
        RUNTIME_ORACLE_HOLD,
        GAMEIMGUI_DISABLE,
        GAMEIMGUI_DISABLE.with_name(GAMEIMGUI_DISABLE_OWNER),
        sandbox_gameimgui_disable,
        sandbox_gameimgui_disable.with_name(GAMEIMGUI_DISABLE_OWNER),
    ])
    if stale_lease_recovered:
        print("recovered interrupted rollback acceptance lease", flush=True)
        if not args.no_launch:
            kill_clients()
            clear_requests(roots)
            time.sleep(2.0)
    gameimgui_suspended = suspend_gameimgui_markers(
        [GAMEIMGUI_DISABLE, sandbox_gameimgui_disable]
    )
    if gameimgui_suspended:
        print("temporarily disabled GameImGui for focused rollback run",
              flush=True)
    oracle_suspended = suspend_runtime_oracle()
    if oracle_suspended:
        print("temporarily disabled RuntimeOracle for focused rollback run",
              flush=True)
    sandbox_dll = sandbox_deployed_dll(
        args.sandbox_root, args.sandbox_box
    )
    if args.clean_start:
        kill_clients()
        clear_requests(roots)
        time.sleep(2.0)
    cache = ProcessCache()
    launch_needed = not args.no_launch \
        and len(cache.read(force=True)) != 2
    if launch_needed:
        deploy_selected_candidate(args.built_dll.resolve(), sandbox_dll)
    require_deployment_preflight(sandbox_dll, args.built_dll.resolve())
    require_expected_artifact_hash(
        sandbox_dll, args.expected_artifact_sha256,
        built_dll=args.built_dll.resolve())
    if launch_needed:
        launch_clients(args)
    evidence_identity = capture_evidence_identity(
        sandbox_dll, args.built_dll.resolve())
    roles = wait_for_clients(cache, args.launch_timeout)
    args.expected_schema_id = wait_for_fresh_horsemod_traces(
        roots, roles, args.rollback_window, args.expected_schema_id,
        timeout=args.launch_timeout)
    bind_consumed_input_sidecar_schema(args)

    run_id = "stock-online-" + datetime.now().strftime("%Y%m%d-%H%M%S")
    secret = secrets.token_hex(24)
    request_generation = time.time_ns() & 0xFFFFFFFFFFFFFFFF
    marker = f"rollback_host_room_ready_{run_id}.ready"
    barrier = StockBarrier(marker)
    arm_live_run_cleanup(roots, barrier)
    barrier.clear(roots)
    states = [
        RoleState("host", HOST_SAVED,
                  IncrementalTraceReader(HOST_SAVED, run_id, roles["host"])),
        RoleState("sandbox", sandbox_saved,
                  IncrementalTraceReader(
                      sandbox_saved, run_id, roles["sandbox"])),
    ]
    for state in states:
        state.process_create_time = psutil.Process(
            roles[state.role]).create_time()
    request_payloads = {
        state.role: request_text(
            args, state.role, run_id, secret, marker,
            request_generation
        )
        for state in states
    }
    request_hashes = {
        role: hashlib.sha256(payload.encode("utf-8")).hexdigest()
        for role, payload in request_payloads.items()
    }
    publish_live_request_files(states, request_payloads)

    if args.mode == "stock-online-attach":
        if args.callback_inventory_diagnostic:
            print("Callback inventory diagnostic armed. Put both clients in "
                  "the same private Casual match; no rollback hooks or "
                  "ownership will be enabled.")
        else:
            print("Attach mode armed. Put both clients in the same private "
                  "Casual match; ownership begins only at a safe frame-zero "
                  "boundary.")
    elif args.callback_inventory_diagnostic:
        print("Automated callback inventory diagnostic armed. The stock "
              "driver will create and join the private room, synchronize "
              "characters and stage, then stop before rollback hooks.")
    elif args.native_correction_diagnostic:
        print("Automated native correction diagnostic armed. The script "
              "selects non-DLC fighters and a fixed arena, proves one "
              "rollback correction, then stops before round transition.")

    deadline = time.monotonic() + args.setup_timeout + args.active_seconds
    match_complete_deadline_armed = False
    last_print = 0.0
    ready_blocked_since = 0.0
    battle_seen_since = 0.0
    ready_handoff_since = 0.0
    hooks_armed_since = 0.0
    diagnostic_first_expected_stop_at = 0.0
    presentation_checkpoint_wait_started = 0.0
    native_controller_phase = -1
    native_controller_phase_started = 0.0
    args.native_controller_phase_boundaries_qpc = []
    args.native_controller_acknowledgements = []
    last_resource_sample = 0.0
    recovery_started = time.monotonic()
    recovery_evidence: dict[str, Any] = {
        "requested": bool(args.test_peer_loss_role
                          or args.test_sandbox_steam_exit),
        "classification": "application-level-local-stress",
        "triggered": False,
        "target": args.test_peer_loss_role
            or ("sandbox-steam" if args.test_sandbox_steam_exit else None),
        "phase": args.test_peer_loss_phase
            or ("active" if args.test_sandbox_steam_exit else None),
        "target_pids": [],
        "target_exit_observed": False,
        "fail_closed_observed": False,
        "pre_loss_ready": False,
        "pre_loss_status_qpc": {},
        "post_loss_failure_samples": {},
    }
    battle_sample_offsets: dict[str, int] = {}
    failures: list[str] = []
    primary_complete = False
    cleanup: dict[str, Any] = {"ok": False, "skipped": True}
    replay_oracle_comparison = None
    replay_input_comparison = None
    replay_correction_witness = None
    early_terminal_cleanup: dict[str, Any] | None = None
    report_path = args.report or (
        REPO / "reports" / "rollback_two_client" / f"{run_id}.json"
    )
    primary_report_path = immutable_primary_report_path(report_path)
    try:
        while time.monotonic() < deadline:
            for state in states:
                state.poll()
            now = time.monotonic()
            if now - last_resource_sample >= 1.0:
                for state in states:
                    state.sample_process_resources(roles[state.role])
                last_resource_sample = now
            active_elapsed = 0.0
            if all(state.active_started_qpc for state in states):
                if args.require_match_complete \
                        and not match_complete_deadline_armed:
                    deadline = live_acceptance_deadline_after_activation(
                        deadline, now, True, args.match_complete_timeout)
                    match_complete_deadline_armed = True
                active_elapsed = min(
                    (int(state.status.get("ts_qpc", 0) or 0)
                     - state.active_started_qpc) / QPC_FREQUENCY
                    for state in states
                ) if QPC_FREQUENCY else 0.0
            transition_observed = any(
                state.status.get("state_name")
                    == "waiting-for-round-transition"
                or (state.active_started_qpc
                    and state.status.get("round_phase_name")
                        not in (None, "active"))
                for state in states
            )
            requested_phase_ready = (
                args.test_peer_loss_phase == "bootstrap"
                and now - recovery_started >= 3.0
                and not all(state.active_started_qpc for state in states)
                and all(
                    bool(state.status.get("steam_session_valid"))
                    and bool(state.status.get("steam_key_confirmed"))
                    and bool(state.status.get("peer_ready"))
                    and _trace_int(state.status.get("steam_local_id")) != 0
                    and _trace_int(state.status.get("steam_remote_id")) != 0
                    for state in states)
            ) or (
                args.test_peer_loss_phase == "active"
                and active_elapsed >= 5.0
            ) or (
                args.test_peer_loss_phase == "round-transition"
                and transition_observed
            )
            if args.test_peer_loss_role \
                    and not recovery_evidence["triggered"] \
                    and requested_phase_ready:
                target_pid = roles[args.test_peer_loss_role]
                recovery_evidence["pre_loss_clients"] = {
                    state.role: {"status": dict(state.status)}
                    for state in states
                }
                recovery_evidence["pre_loss_ready"] = all(
                    bool(state.status.get("steam_session_valid"))
                    and bool(state.status.get("steam_key_confirmed"))
                    and bool(state.status.get("peer_ready"))
                    for state in states)
                recovery_evidence["pre_loss_status_qpc"] = {
                    state.role: _trace_int(
                        state.status.get("ts_qpc"))
                    for state in states
                }
                terminate_verified_game_process(target_pid)
                recovery_evidence.update({
                    "triggered": True,
                    "trigger_monotonic": now,
                    "target_pids": [target_pid],
                })
            if args.test_sandbox_steam_exit \
                    and not recovery_evidence["triggered"] \
                    and active_elapsed >= 5.0:
                recovery_evidence["pre_loss_clients"] = {
                    state.role: {"status": dict(state.status)}
                    for state in states
                }
                recovery_evidence["pre_loss_ready"] = all(
                    bool(state.status.get("steam_session_valid"))
                    and bool(state.status.get("steam_key_confirmed"))
                    and bool(state.status.get("peer_ready"))
                    for state in states)
                recovery_evidence["pre_loss_status_qpc"] = {
                    state.role: _trace_int(
                        state.status.get("ts_qpc"))
                    for state in states
                }
                terminated = terminate_sandbox_steam_processes(
                    args.sandboxie, args.sandbox_box)
                recovery_evidence.update({
                    "triggered": True,
                    "trigger_monotonic": now,
                    "target_pids": terminated,
                })
            live_pids = {
                int(process["ProcessId"])
                for process in cache.read()
            }
            exited = [
                role for role, pid in roles.items()
                if pid not in live_pids
            ]
            if recovery_evidence["triggered"]:
                expected_exited = (
                    args.test_peer_loss_role in exited
                    if args.test_peer_loss_role else
                    not sandbox_steam_ready(sandbox_process_names(
                        args.sandboxie, args.sandbox_box))
                )
                unexpected_exited = [
                    role for role in exited
                    if role != args.test_peer_loss_role
                ] if args.test_peer_loss_role else []
                recovery_evidence["target_exit_observed"] = bool(
                    expected_exited)
                survivors = [
                    state for state in states
                    if state.role not in exited
                ]
                fail_closed_evidence = recovery_fail_closed_evidence(
                    survivors,
                    recovery_evidence.get(
                        "pre_loss_status_qpc", {}),
                    bool(recovery_evidence.get("pre_loss_ready")))
                recovery_evidence["post_loss_failure_samples"] = \
                    fail_closed_evidence["post_loss_failure_samples"]
                recovery_evidence["recognized_terminal_roles"] = \
                    fail_closed_evidence["recognized_terminal_roles"]
                fail_closed = bool(fail_closed_evidence["ok"])
                recovery_evidence["fail_closed_observed"] = fail_closed
                if unexpected_exited:
                    failures = [
                        f"{role}:unexpected-process-exited"
                        for role in unexpected_exited
                    ]
                    break
                if expected_exited and fail_closed:
                    failures = []
                    break
                if now - float(recovery_evidence.get(
                        "trigger_monotonic", now)) >= 15.0:
                    failures = ["recovery-fail-closed-timeout"]
                    break
                time.sleep(0.2)
                continue
            if exited:
                failures = [f"{role}:process-exited" for role in exited]
                break
            if args.mode == "stock-online-local-lab":
                barrier.update(states)
                if barrier.failure:
                    failures = [f"stock-barrier:{barrier.failure}"]
                    break
            fatal = [state for state in states
                     if state.status.get("state_name") == "fatal"
                     or int(state.status.get("state", -1)) == FATAL_STATE]
            if args.callback_inventory_diagnostic:
                unexpected_fatal = [state for state in fatal
                    if state.status.get("failure") not in
                        CALLBACK_INVENTORY_EXPECTED_STOPS]
                if unexpected_fatal:
                    failures = [
                        f"{state.role}:fatal:"
                        f"{state.status.get('failure', 'unknown')}"
                        for state in unexpected_fatal
                    ]
                    break
                if fatal:
                    diagnostic_first_expected_stop_at = \
                        diagnostic_first_expected_stop_at or now
                    diagnostic_failures = \
                        callback_inventory_diagnostic_failures(
                            states, args.left_character_code,
                            args.right_character_code, args.stage)
                    if len(fatal) == 2 and not diagnostic_failures:
                        failures = []
                        break
                    if now - diagnostic_first_expected_stop_at >= 5.0:
                        failures = diagnostic_failures or [
                            "callback-inventory-bilateral-timeout"]
                        break
                if now - last_print >= 1.0:
                    print(" ".join(
                        f"{state.role}:state="
                        f"{state.status.get('state_name', '?')} "
                        f"inventory_events="
                        f"{len(state.callback_inventory_events)}"
                        for state in states), flush=True)
                    last_print = now
                time.sleep(0.2)
                continue
            if fatal:
                failures = [
                    f"{state.role}:fatal:{state.status.get('failure', 'unknown')}"
                    for state in fatal
                ]
                break
            seed_setup_failures = replay_seed_setup_failures(
                states, args.replay_input_enabled)
            if seed_setup_failures:
                failures = seed_setup_failures
                break
            hooks_armed = all(
                state.status.get("state_name")
                    == "waiting-for-launch-barrier"
                or int(state.status.get("state", -1)) == HOOKS_ARMED_STATE
                for state in states
            )
            if hooks_armed:
                hooks_armed_since = hooks_armed_since or now
                if now - hooks_armed_since >= ACTIVATION_TIMEOUT_SECONDS:
                    failures = ["rollback-activation-timeout"]
                    break
            else:
                hooks_armed_since = 0.0
            host = next(state for state in states if state.role == "host")
            if (
                barrier.peer_ready_released
                and host.stage.get("ready_request_failure")
                    == "ready-channel-cannot-send"
            ):
                ready_blocked_since = ready_blocked_since or now
                if now - ready_blocked_since >= 5.0:
                    failures = ["host:ready-channel-cannot-send"]
                    break
            else:
                ready_blocked_since = 0.0
            if (
                args.mode == "stock-online-local-lab"
                and bool(host.stage.get("create_callback_seen"))
                and not bool(host.stage.get("create_callback_result"))
            ):
                failures = ["host:OnCreateSession-result-false"]
                break
            if args.mode == "stock-online-local-lab":
                failed_rates = [
                    state for state in states
                    if bool(state.stage.get("stock_menu_rate_complete"))
                    and not bool(state.stage.get("stock_menu_rate_ok"))
                ]
                if failed_rates:
                    failures = [
                        f"{state.role}:menu-rate="
                        f"{float(state.stage.get('stock_menu_tick_rate_hz', 0.0)):.2f}Hz"
                        for state in failed_rates
                    ]
                    break
                if requires_stock_battle_rate_gate(args):
                    failed_battle_rates = [
                        state for state in states
                        if bool(state.stage.get(
                            "stock_battle_rate_complete"))
                        and not bool(state.stage.get("stock_battle_rate_ok"))
                    ]
                    if failed_battle_rates:
                        failures = [
                            f"{state.role}:battle-rate="
                            f"{float(state.stage.get('stock_battle_tick_rate_hz', 0.0)):.2f}Hz"
                            for state in failed_battle_rates
                        ]
                        failures.extend(stock_battle_ready_order_failures(
                            states, barrier))
                        break
                permanent_setup_failures = {
                    "find-player-session-failed",
                    "join-player-session-failed",
                    "join-session-result-false",
                }
                failed_setup = [
                    state for state in states
                    if state.stage.get("failure") in permanent_setup_failures
                ]
                if failed_setup:
                    failures = [
                        f"{state.role}:{state.stage.get('failure')}"
                        for state in failed_setup
                    ]
                    break
                failed_connect = [
                    state for state in states
                    if state.role == "sandbox"
                    and bool(state.stage.get("stock_native_event_dispatched"))
                    and int(state.stage.get("native_connect_state", -1)) == 5
                    and str(state.stage.get(
                        "native_session_connection", "0x0")) == "0x0"
                ]
                if failed_connect:
                    failures = ["sandbox:native-connect-failed-state-5"]
                    break
            ready_handoff_complete = all(
                state.ready_handoff_observed for state in states
            )
            native_battle_running = all(
                bool(state.stage.get("stock_native_battle_tick_seen"))
                for state in states
            )
            if ready_handoff_complete and not native_battle_running:
                if not ready_handoff_since:
                    ready_handoff_since = now
                elif now - ready_handoff_since >= \
                        BATTLE_ENTRY_TIMEOUT_SECONDS:
                    failures = [
                        f"{state.role}:waiting-for-opponent-"
                        "native-battle-timeout"
                        for state in states
                        if not state.stage.get("stock_native_battle_tick_seen")
                    ]
                    break
            elif native_battle_running or not ready_handoff_complete:
                ready_handoff_since = 0.0
            if now - last_print >= 1.0:
                summary = " ".join(
                    f"{state.role}:state={state.status.get('state', '?')} "
                    f"save/load/rb={state.status.get('saves', 0)}/"
                    f"{state.status.get('loads', 0)}/"
                    f"{state.status.get('rollback_advances', 0)} "
                    f"scene={state.stage.get('current_scene_class', '?')} "
                    f"native_ticks={state.stage.get('stock_battle_frame_advances', 0)}"
                    for state in states
                )
                print(summary, flush=True)
                last_print = now
            if args.setup_only and all(
                bool(state.stage.get("stock_native_battle_tick_seen"))
                for state in states
            ):
                if not battle_seen_since:
                    battle_seen_since = now
                elif not battle_sample_offsets \
                        and now - battle_seen_since >= BATTLE_WARMUP_SECONDS:
                    battle_sample_offsets = {
                        state.role: max(0, len(state.status_samples) - 1)
                        for state in states
                    }
                elif battle_sample_offsets \
                        and now - battle_seen_since >= \
                            BATTLE_WARMUP_SECONDS + STABLE_SECONDS:
                    failures = setup_failures(states, args, barrier)
                    for state in states:
                        samples = state.status_samples[
                            battle_sample_offsets[state.role]:]
                        observed = rate_window(samples, False)
                        state.setup_battle_rate = observed
                        if not observed["ok"]:
                            failures.append(
                                f"{state.role}:battle-rate="
                                f"{observed['hz']:.2f}Hz/"
                                f"{observed['seconds']:.1f}s"
                            )
                    break
            if all(state.active_started_qpc for state in states):
                active_seconds = active_elapsed
                if args.native_controller_preflight:
                    phase_seconds = args.native_controller_phase_seconds
                    next_phase = None
                    if native_controller_phase < 0:
                        next_phase = 0
                    elif native_controller_phase < 3 \
                            and now - native_controller_phase_started \
                                >= phase_seconds:
                        next_phase = native_controller_phase + 1
                    if next_phase is not None:
                        instructions = (
                            "Release both controllers. Press Enter only "
                            "when both are neutral.",
                            "Keep the Sandboxie controller neutral. Press "
                            "Enter, then use only the host controller.",
                            "Release the host controller. Press Enter, then "
                            "use only the Sandboxie controller.",
                            "Release the Sandboxie controller. Press Enter "
                            "to confirm the isolation phases are complete.",
                        )
                        labels = (
                            "neutral", "host-only",
                            "sandbox-only", "complete")
                        try:
                            input(
                                f"native controller phase "
                                f"{next_phase + 1}/4: "
                                f"{instructions[next_phase]} ")
                        except EOFError:
                            failures.append(
                                "native-controller-ack-input-unavailable")
                            break
                        for state in states:
                            state.poll()
                        boundary_qpc = min(
                            _trace_int(state.status.get("ts_qpc"))
                            for state in states)
                        native_controller_phase = next_phase
                        native_controller_phase_started = time.monotonic()
                        args.native_controller_phase_boundaries_qpc.append(
                            boundary_qpc)
                        args.native_controller_acknowledgements.append({
                            "phase": labels[next_phase],
                            "acknowledged": True,
                            "status_qpc": boundary_qpc,
                            "wall_time": utc_now(),
                        })
                if live_acceptance_requirement_ready(
                        active_seconds, args.active_seconds,
                        bool(getattr(args, "require_match_complete", False)),
                        [state.status for state in states]):
                    if args.require_round_rearm and (
                        not bilateral_round_rearm_ready(
                            [state.status for state in states],
                            [state.status_samples for state in states],
                            args.replay_round,
                            args.replay_round_start_frames)
                        or any(latest_active_round_seconds(state)
                               < args.required_round_active_seconds
                               for state in states)
                    ):
                        time.sleep(0.2)
                        continue
                    confirmed_failures = confirmed_frame_gate_failures(
                        states, args.min_confirmed_frame,
                        args.active_seconds)
                    match_complete_ready = \
                        match_complete_terminal_pair_ready([
                            state.status for state in states])
                    if confirmed_frame_gate_should_wait(
                            confirmed_failures,
                            bool(getattr(
                                args, "require_match_complete", False)),
                            match_complete_ready):
                        time.sleep(0.2)
                        continue
                    if confirmed_failures:
                        failures = core_failures(
                            states, args, barrier, request_generation)
                        break
                    checkpoint_failures = \
                        presentation_checkpoint_gate_failures(
                            states, args.require_presentation_checkpoint,
                            required_rounds=(
                                2 if args.require_round_rearm else 1))
                    if checkpoint_failures == [
                            "presentation-checkpoint:"
                            "presentation-checkpoint-no-common-convergence"]:
                        if not presentation_checkpoint_wait_started:
                            presentation_checkpoint_wait_started = \
                                time.monotonic()
                        if time.monotonic() \
                                < presentation_checkpoint_wait_started + 5.0:
                            time.sleep(0.2)
                            continue
                    if checkpoint_failures:
                        failures = core_failures(
                            states, args, barrier, request_generation)
                        failures.extend(checkpoint_failures)
                        break
                    failures = core_failures(
                        states, args, barrier, request_generation)
                    break
            waiting_for_stock_handoff = (
                all(bool(state.stage.get("stock_selection_bilateral_ok"))
                    for state in states)
                and not ready_handoff_complete
            )
            time.sleep(0.005 if waiting_for_stock_handoff else 0.2)
        else:
            failures = callback_inventory_diagnostic_failures(
                states, args.left_character_code,
                args.right_character_code, args.stage,
                require_expected_stop=False) + [
                    "callback-inventory-diagnostic-timeout"] \
                if args.callback_inventory_diagnostic else [
                    "acceptance-timeout"]
        primary_complete = True
    finally:
        # Freeze the test-ending observations before releasing ownership.
        # Request removal, reusable cleanup, and process shutdown are separate
        # lifecycle operations and may legitimately publish different native
        # world/round state.  They must never rewrite the primary verdict.
        evidence_states = freeze_role_states(states)
        # Availability evidence is an independent test-tool gate. A later
        # rollback fatal must not hide that the native filters were unused or
        # that the DLC character was controlled by the wrong Steam account.
        for state in evidence_states:
            for failure in replay_test_selection_availability_failures(
                    state, args):
                if failure not in failures:
                    failures.append(failure)
        # Stop ownership and close explicitly disposable clients before any
        # potentially long trace comparison. Evidence collection operates on
        # the now-immutable trace files and retained live identity samples.
        # Native-correction diagnostics are exempt because they must first
        # prove post-request pass-through in the still-running processes.
        try:
            clear_requests(roots)
        except Exception as error:
            failures.append(
                "request-clear-before-comparison-failed:"
                f"{type(error).__name__}:{error}")
        try:
            barrier.clear(roots)
        except Exception as error:
            failures.append(
                "barrier-clear-before-comparison-failed:"
                f"{type(error).__name__}:{error}")
        if args.shutdown_clients and not args.native_correction_diagnostic:
            try:
                early_terminal_cleanup = explicit_client_shutdown_evidence(
                    1 if args.test_peer_loss_role else 2)
                cleanup = early_terminal_cleanup
                if not cleanup["ok"]:
                    failures.append(cleanup["reason"])
            except Exception as error:
                early_terminal_cleanup = {
                    "ok": False,
                    "skipped": False,
                    "reason": "early-client-shutdown-exception:"
                        f"{type(error).__name__}:{error}",
                    "terminal_shutdown_verified": False,
                }
                cleanup = early_terminal_cleanup
                failures.append(cleanup["reason"])
        try:
            # The detailed replay verdict is primary test evidence. Capture it
            # while the request and exact live trace identity still exist.
            try:
                replay_oracle_comparison, replay_input_comparison, \
                    replay_correction_witness, replay_failures = \
                    collect_replay_comparisons(evidence_states, args)
                for failure in replay_failures:
                    if failure not in failures:
                        failures.append(failure)
            except Exception as error:
                failures.append(
                    "replay-comparison-failed:"
                    f"{type(error).__name__}:{error}")
            # Persist an immutable sibling checkpoint before cleanup can time
            # out or fail. Checkpoint failure must never bypass cleanup.
            if args.mode == "stock-online-local-lab":
                for failure in battle_asset_release_timing_failures(
                        evidence_states, barrier, request_generation):
                    if failure not in failures:
                        failures.append(failure)
            primary_test_ok, primary_test_failures = primary_test_result(
                failures, primary_complete)
            checkpoint_failures = list(primary_test_failures)
            checkpoint_requires_post_cleanup = (
                args.native_correction_diagnostic
                or (not args.callback_inventory_diagnostic
                    and not args.setup_only
                    and not args.shutdown_clients)
            )
            if checkpoint_requires_post_cleanup:
                checkpoint_failures.append("cleanup-pending")
            checkpoint_cleanup = early_terminal_cleanup or {
                "ok": bool(args.callback_inventory_diagnostic),
                "skipped": True,
                "reason": "pre-hook-diagnostic-no-owned-boundary"
                    if args.callback_inventory_diagnostic
                    else "cleanup-pending",
            }
            primary_checkpoint = report_for(
                evidence_states, args, run_id, roles,
                checkpoint_failures, barrier,
                checkpoint_cleanup, evidence_identity, request_hashes)
            primary_checkpoint["primary_test_ok"] = primary_test_ok
            primary_checkpoint["primary_test_failures"] = (
                primary_test_failures)
            if checkpoint_requires_post_cleanup:
                primary_checkpoint["ok"] = False
                primary_checkpoint["verdict"] = "incomplete"
                primary_checkpoint["acceptance_eligible"] = False
            primary_checkpoint["primary_checkpoint"] = True
            primary_checkpoint["primary_report_path"] = str(
                primary_report_path)
            attach_replay_comparisons(
                primary_checkpoint, replay_oracle_comparison,
                replay_input_comparison, replay_correction_witness)
            publish_primary_checkpoint(
                primary_report_path, primary_checkpoint, failures)
        except Exception as error:
            failures.append(
                "primary-report-publication-failed:"
                f"{type(error).__name__}:{error}")
        finally:
            # Removing the request releases HorseMod ownership. Clients are
            # left running by default; explicit process shutdown is opt-in.
            try:
                clear_requests(roots)
            except Exception as error:
                failures.append(
                    "request-clear-failed:"
                    f"{type(error).__name__}:{error}")
            try:
                barrier.clear(roots)
            except Exception as error:
                failures.append(
                    "barrier-clear-failed:"
                    f"{type(error).__name__}:{error}")
            try:
                if args.callback_inventory_diagnostic:
                    cleanup = {
                        "ok": True, "skipped": True,
                        "reason": "pre-hook-diagnostic-no-owned-boundary",
                    }
                elif args.native_correction_diagnostic:
                    pass_through_cleanup = verify_native_correction_pass_through(
                        args, roots, roles)
                    if args.shutdown_clients:
                        terminal_cleanup = explicit_client_shutdown_evidence()
                        cleanup = {
                            "ok": bool(pass_through_cleanup.get("ok"))
                                and bool(terminal_cleanup.get("ok")),
                            "skipped": False,
                            "reason": (
                                "native-correction-pass-through-and-"
                                "client-shutdown-proven"
                                if pass_through_cleanup.get("ok")
                                and terminal_cleanup.get("ok")
                                else "native-correction-cleanup-incomplete"
                            ),
                            "pass_through": pass_through_cleanup,
                            "terminal_shutdown": terminal_cleanup,
                            "terminal_shutdown_verified": bool(
                                terminal_cleanup.get(
                                    "terminal_shutdown_verified")),
                        }
                    else:
                        cleanup = pass_through_cleanup
                elif args.shutdown_clients:
                    cleanup = early_terminal_cleanup \
                        or explicit_client_shutdown_evidence()
                    if not cleanup["ok"] \
                            and cleanup["reason"] not in failures:
                        failures.append(cleanup["reason"])
                else:
                    cleanup = cleanup_clients(args, roots, roles)
            except Exception as error:
                cleanup = {
                    "ok": False,
                    "skipped": False,
                    "reason": "cleanup-exception:"
                        f"{type(error).__name__}:{error}",
                }
                failures.append(cleanup["reason"])
            finally:
                restore_runtime_oracle()
                restore_gameimgui_markers()
                restore_marker_lease()

    effect_gate_reached = any(
        int(state.status.get("saves", 0) or 0) > 0
        for state in evidence_states)
    pass_through_result = cleanup.get("pass_through", cleanup)
    if args.native_correction_diagnostic \
            and not pass_through_result.get("ok"):
        failures.append("final:native-hook-pass-through-not-proven")
    if args.shutdown_clients \
            and not cleanup.get("terminal_shutdown_verified"):
        failures.append("final:client-shutdown-not-proven")
    if not recovery_evidence["requested"]:
        failures.extend(reusable_cleanup_failures(args, cleanup))
    # Duration alone cannot turn an arbitrary replay into a presentation
    # fixture. Only an explicitly requested checkpoint is a final-effects gate.
    if (not args.callback_inventory_diagnostic
            and not args.setup_only and args.require_presentation_checkpoint
            and effect_gate_reached):
        failures.extend(final_effect_failures(
            evidence_states, require_round=(args.require_round_rearm
                                            or args.active_seconds >= 120.0)))
    report = report_for(
        evidence_states, args, run_id, roles, failures, barrier, cleanup,
        evidence_identity, request_hashes)
    report["primary_report_path"] = str(primary_report_path)
    attach_replay_comparisons(
        report, replay_oracle_comparison, replay_input_comparison,
        replay_correction_witness)
    if recovery_evidence["requested"]:
        recovery_evidence["requests_cleared"] = all(
            not (root / "rollback_lab_request.txt").exists()
            for root in roots)
        recovery_evidence["barrier_cleared"] = all(
            not (root / marker).exists() for root in roots)
        recovery_failures = list(failures)
        if not recovery_evidence["triggered"]:
            recovery_failures.append("recovery-trigger-not-reached")
        if recovery_evidence["triggered"] \
                and not recovery_evidence["pre_loss_ready"]:
            recovery_failures.append("recovery-pre-loss-not-ready")
        if not recovery_evidence["target_exit_observed"]:
            recovery_failures.append("recovery-target-exit-not-observed")
        if not recovery_evidence["fail_closed_observed"]:
            recovery_failures.append("recovery-fail-closed-not-observed")
        if not recovery_evidence["requests_cleared"]:
            recovery_failures.append("recovery-request-not-cleared")
        if not recovery_evidence["barrier_cleared"]:
            recovery_failures.append("recovery-barrier-not-cleared")
        recovery_evidence["failures"] = recovery_failures
        recovery_evidence["ok"] = not recovery_failures
        report["recovery_evidence"] = recovery_evidence
        report["ok"] = recovery_evidence["ok"]
        report["verdict"] = (
            "expected-fail-closed-pass"
            if report["ok"] else "recovery-stress-failed")
        report["acceptance_eligible"] = False
    atomic_json(report_path, report)
    try:
        print(f"report={report_path}")
        print("PASS" if report["ok"] else "FAIL: " + ", ".join(failures))
    except OSError:
        # The primary and final reports are already durable. A detached
        # console must not turn a completed game test into infrastructure
        # failure or overwrite its evidence.
        pass
    return 0 if report["ok"] else 1


def main() -> int:
    global BUILT_DLL
    args = parse_args()
    BUILT_DLL = args.built_dll.resolve()
    if args.selftest or args.policy_lint or args.write_candidate_manifest:
        return _main(args)
    try:
        return _main(args)
    finally:
        # This guard begins before marker acquisition and therefore also runs
        # for setup exceptions and KeyboardInterrupt before the polling loop.
        release_live_run_resources()


if __name__ == "__main__":
    try:
        sys.exit(main())
    except Exception as error:
        parsed = parse_args()
        if (parsed.selftest or parsed.policy_lint
                or parsed.write_candidate_manifest):
            print(
                "rollback stock-online standalone operation failed: "
                f"{type(error).__name__}:{error}",
                file=sys.stderr,
            )
            sys.exit(2)
        restore_runtime_oracle()
        restore_gameimgui_markers()
        restore_marker_lease()
        failed_sandbox_dll = sandbox_deployed_dll(
            parsed.sandbox_root, parsed.sandbox_box
        )
        failure_report = {
            "report_schema_version": REPORT_SCHEMA_VERSION,
            "oracle_schema_version": ROLLBACK_ORACLE_SCHEMA_VERSION,
            "ok": False,
            "verdict": "infrastructure-failure",
            "acceptance_classification":
                "setup-ready" if parsed.setup_only else "rollback-core-gate",
            "setup_only": parsed.setup_only,
            "generated_at": utc_now(),
            "failures": [
                f"{type(error).__name__}:{error}"
            ],
            "evidence_identity": capture_evidence_identity(
                failed_sandbox_dll, parsed.built_dll.resolve()
            ),
        }
        failure_path = parsed.report or (
            REPO / "reports" / "rollback_two_client" /
            f"infrastructure-failure-{datetime.now():%Y%m%d-%H%M%S}.json"
        )
        if failure_path.exists():
            try:
                existing = json.loads(failure_path.read_text(
                    encoding="utf-8"))
            except (OSError, ValueError):
                existing = {}
            if existing.get("run_id") and "clients" in existing:
                restore_runtime_oracle()
                sys.exit(2)
        atomic_json(failure_path, failure_report)
        try:
            print(f"report={failure_path}")
            print("FAIL: " + failure_report["failures"][0],
                  file=sys.stderr)
        except OSError:
            pass
        sys.exit(2)
